  cumulativeCost: number;
  equity: number;
}

export const TAX_RATES = {
  SHORT_TERM: 0.3963, // Under 5 years (Income tax 30% + Resident tax 9% + Reconstruction 0.63%)
  LONG_TERM: 0.20315, // Over 5 years (Income tax 15% + Resident tax 5% + Reconstruction 0.315%)
};

export const BROKERAGE_FEE_RATE = 0.03;
export const BROKERAGE_FEE_FIXED = 60000;
export const CONSUMPTION_TAX = 1.1;

export const INITIAL_VALUES = {
  purchasePrice: 50000000,
