import { SimulationInputs, SimulationResults, YearlyData } from '../types';
import { TAX_RATES, BROKERAGE_FEE_RATE, BROKERAGE_FEE_FIXED, CONSUMPTION_TAX } from '../constants';

export const calculateMortgagePayment = (principal: number, annualRate: number, years: number) => {
  if (annualRate === 0) return principal / (years * 12);
  const monthlyRate = annualRate / 100 / 12;
  const numberOfPayments = years * 12;
  return (principal * monthlyRate * Math.pow(1 + monthlyRate, numberOfPayments)) / (Math.pow(1 + monthlyRate, numberOfPayments) - 1);
};

export const calculateMortgageBalance = (principal: number, annualRate: number, years: number, paymentsMade: number) => {
  const monthlyRate = annualRate / 100 / 12;
  const numberOfPayments = years * 12;
  if (annualRate === 0) return principal * (1 - paymentsMade / numberOfPayments);
  return principal * (Math.pow(1 + monthlyRate, numberOfPayments) - Math.pow(1 + monthlyRate, paymentsMade)) / (Math.pow(1 + monthlyRate, numberOfPayments) - 1);
};

export const calculateSimulation = (inputs: SimulationInputs): SimulationResults => {
  const {
    purchasePrice, initialCosts, downPayment, mortgageTerm, interestRate,
    maintenanceFee, repairFund, fixedAssetTax, yearsHeld, appreciationRate, isPrimaryResidence
  } = inputs;

  const loanAmount = purchasePrice - downPayment;
  const monthlyPayment = calculateMortgagePayment(loanAmount, interestRate, mortgageTerm);

  const yearlyData: YearlyData[] = [];
  let cumulativeCost = initialCosts + downPayment;

  for (let y = 0; y <= yearsHeld; y++) {
    const propertyValue = purchasePrice * Math.pow(1 + appreciationRate / 100, y);
    const balance = calculateMortgageBalance(loanAmount, interestRate, mortgageTerm, y * 12);

    if (y > 0) {
      const annualMortgage = monthlyPayment * 12;
      const annualUpkeep = (maintenanceFee + repairFund) * 12 + fixedAssetTax;
      cumulativeCost += annualMortgage + annualUpkeep;
    }

    yearlyData.push({
      year: y,
      propertyValue,
      mortgageBalance: balance,
      cumulativeCost,
      equity: propertyValue - balance
    });
  }

  const finalPropertyValue = yearlyData[yearsHeld].propertyValue;
  const remainingBalance = yearlyData[yearsHeld].mortgageBalance;

  // Selling Costs
  const sellingBrokerageFee = (finalPropertyValue * BROKERAGE_FEE_RATE + BROKERAGE_FEE_FIXED) * CONSUMPTION_TAX;
  const otherSellingCosts = 50000; // General registration fees/stamp duty
  const totalSellingCosts = sellingBrokerageFee + otherSellingCosts;

  // Tax Calculation
  // Profit = Selling Price - (Purchase Price + Purchase Expenses) - Selling Expenses
  const capitalGain = finalPropertyValue - (purchasePrice + initialCosts) - totalSellingCosts;
  const taxableGain = isPrimaryResidence ? Math.max(0, capitalGain - 30000000) : Math.max(0, capitalGain);

  const taxRate = yearsHeld > 5 ? TAX_RATES.LONG_TERM : TAX_RATES.SHORT_TERM;
  const taxAmount = taxableGain * taxRate;

  const totalInflow = finalPropertyValue;
  const totalOutflow = cumulativeCost + totalSellingCosts + taxAmount + remainingBalance;
  const netProfit = totalInflow - totalOutflow + (initialCosts + downPayment); // Adjusting because initial cash was an outflow

  // Real Net Cash Position: (Cash after sale) - (Total Cash Put In Over Years)
  const totalInvestedCash = cumulativeCost;
  const cashAtHandAfterSale = finalPropertyValue - remainingBalance - totalSellingCosts - taxAmount;
  const finalNetResult = cashAtHandAfterSale - totalInvestedCash;

  return {
    purchasePrice,
    initialTotalCost: initialCosts,
    sellingPrice: finalPropertyValue,
    totalMaintenanceCosts: (maintenanceFee + repairFund) * 12 * yearsHeld + fixedAssetTax * yearsHeld,
    totalMortgagePayments: monthlyPayment * 12 * yearsHeld,
    remainingMortgageBalance: remainingBalance,
    sellingCosts: totalSellingCosts,
    taxAmount,
    netProfit: finalNetResult,
    totalOutflow: cumulativeCost + totalSellingCosts + taxAmount + remainingBalance,
    totalInflow: finalPropertyValue,
    yearlyData
  };
};

export const formatCurrency = (val: number) => {
  return new Intl.NumberFormat('ja-JP', { style: 'currency', currency: 'JPY', maximumFractionDigits: 0 }).format(val);
};

import { GoogleGenAI } from "@google/genai";
import { SimulationInputs, SimulationResults } from "../types";

export const getAIAnalysis = async (inputs: SimulationInputs, results: SimulationResults) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `
    あなたは不動産投資と住宅購入の専門アドバイザーです。以下のマンション購入シミュレーション結果を分析し、ユーザーに日本語で簡潔かつ論理的なアドバイスを提供してください。

    【購入条件】
    - 購入価格: ${inputs.purchasePrice}円
    - 保有期間: ${inputs.yearsHeld}年
    - 住宅ローン金利: ${inputs.interestRate}%
    - 年間資産価値変動率: ${inputs.appreciationRate}%

    【シミュレーション結果】
    - 最終売却価格予想: ${results.sellingPrice}円
    - 10年間の総支出（維持費・ローン込）: ${results.totalOutflow}円
    - 最終的な純損益: ${results.netProfit}円
    - ローン残債: ${results.remainingMortgageBalance}円
    - 譲渡所得税: ${results.taxAmount}円

    以下の観点を含めてください：
    1. この計画の経済的合理性（得か損か）
    2. 最大のリスク要因
    3. 改善のための提案（売却時期、繰り上げ返済、物件選びのポイントなど）
    4. 市場環境への言及
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
    });
    return response.text;
  } catch (error) {
    console.error("Gemini Error:", error);
    return "AIによる分析中にエラーが発生しました。しばらく経ってから再度お試しください。";
  }
};

