import React, { useState, useEffect, useMemo } from 'react';
import { SimulationInputs, SimulationResults, BuildingType } from './types';
import { INITIAL_VALUES } from './constants';
import { calculateSimulation, formatCurrency } from './utils/calculations';
import { getAIAnalysis, extractPropertyFromUrl } from './services/geminiService';
import { 
  LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, AreaChart, Area,
  BarChart, Bar
} from 'recharts';
import { 
  Building2, 
  TrendingUp, 
  Wallet, 
  ShieldCheck, 
  Info, 
  RefreshCcw, 
  BrainCircuit,
  Calculator,
  AlertTriangle,
  Banknote,
  Activity,
  UserCheck,
  Zap,
  Link as LinkIcon,
  ExternalLink,
  Loader2,
  BadgeDollarSign,
  Clock
} from 'lucide-react';

const App: React.FC = () => {
  const [inputs, setInputs] = useState<SimulationInputs>(INITIAL_VALUES);
  const [results, setResults] = useState<SimulationResults>(calculateSimulation(INITIAL_VALUES));
  const [aiAdvice, setAiAdvice] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);
  const [activeTab, setActiveTab] = useState<'summary' | 'charts' | 'ai'>('summary');

  // URL Import States
  const [propertyUrl, setPropertyUrl] = useState('');
  const [isExtracting, setIsExtracting] = useState(false);
  const [extractedSources, setExtractedSources] = useState<{title: string, uri: string}[]>([]);

  useEffect(() => {
    setResults(calculateSimulation(inputs));
  }, [inputs]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target;
    const checked = (e.target as HTMLInputElement).checked;

    setInputs(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : 
              (name === 'buildingType' ? value : (parseFloat(value) || 0))
    }));
  };

  const handleUrlExtract = async () => {
    if (!propertyUrl) return;
    setIsExtracting(true);
    try {
      const { data, sources } = await extractPropertyFromUrl(propertyUrl);
      setInputs(prev => ({
        ...prev,
        purchasePrice: data.purchasePrice || prev.purchasePrice,
        maintenanceFee: data.maintenanceFee || prev.maintenanceFee,
        repairFund: data.repairFund || prev.repairFund,
        buildingType: (data.buildingType as BuildingType) || prev.buildingType,
        landRatio: data.landRatio || prev.landRatio,
      }));
      setExtractedSources(sources);
      alert(`${data.propertyName || '物件'} の情報を取得・反映しました。`);
    } catch (error: any) {
      alert(error.message);
    } finally {
      setIsExtracting(false);
    }
  };

  const runAiAnalysis = async () => {
    setLoadingAi(true);
    const advice = await getAIAnalysis(inputs, results);
    setAiAdvice(advice.text);
    setLoadingAi(false);
    setActiveTab('ai');
  };

  const chartData = useMemo(() => {
    return results.yearlyData.map(d => ({
      year: `${d.year}年目`,
      "物件価値": Math.round(d.propertyValue / 10000) / 100,
      "ローン残高": Math.round(d.mortgageBalance / 10000) / 100,
      "累計実質支出": Math.round(d.cumulativeCost / 10000) / 100,
      "住宅ローン減税": Math.round(d.taxCredit / 10000) / 100,
      "固定資産税": Math.round(d.yearlyTax / 1000) / 10,
      "純資産額": Math.round((d.propertyValue - d.mortgageBalance) / 10000) / 100
    }));
  }, [results]);

  const getSustainabilityColor = (ratio: number) => {
    if (ratio < 25) return 'text-emerald-500 bg-emerald-50 border-emerald-100';
    if (ratio < 35) return 'text-amber-500 bg-amber-50 border-amber-100';
    return 'text-rose-500 bg-rose-50 border-rose-100';
  };

  const getSustainabilityLabel = (ratio: number) => {
    if (ratio < 25) return '非常に健全';
    if (ratio < 35) return '注意が必要';
    return '危険（要見直し）';
  };

  return (
    <div className="min-h-screen bg-slate-50 pb-20 font-['Inter','Noto_Sans_JP']">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-50 shadow-sm">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="bg-blue-600 p-1.5 rounded-lg">
              <Building2 className="text-white w-6 h-6" />
            </div>
            <h1 className="text-xl font-bold text-slate-800 tracking-tight">Condo Wealth <span className="text-blue-600">Pro</span></h1>
          </div>
          <div className="flex items-center gap-4 text-sm text-slate-500 font-medium">
            <span className="hidden md:block">高精度マンション資産・家計シミュレーター</span>
            <button onClick={() => {setInputs(INITIAL_VALUES); setExtractedSources([]); setPropertyUrl('');}} className="flex items-center gap-1 hover:text-blue-600 transition-colors">
              <RefreshCcw className="w-4 h-4" /> リセット
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 mt-8 grid grid-cols-1 lg:grid-cols-12 gap-8">

        {/* Input Sidebar */}
        <aside className="lg:col-span-4 space-y-6">

          {/* AI URL Import Section */}
          <section className="bg-gradient-to-br from-slate-800 to-slate-900 rounded-2xl shadow-lg p-6 text-white overflow-hidden relative">
            <div className="absolute top-0 right-0 p-4 opacity-10 pointer-events-none">
               <LinkIcon size={80} />
            </div>
            <div className="flex items-center gap-2 mb-4 relative z-10">
              <BrainCircuit className="w-5 h-5 text-blue-400" />
              <h2 className="text-lg font-bold">AIデータ自動取得</h2>
            </div>
            <p className="text-xs text-slate-300 mb-4 leading-relaxed">
              SUUMOなどの物件URLを貼るだけで、価格や諸経費をAIが自動入力します。
            </p>
            <div className="space-y-3 relative z-10">
              <div className="relative">
                <input 
                  type="text" 
                  placeholder="https://suumo.jp/..." 
                  value={propertyUrl}
                  onChange={(e) => setPropertyUrl(e.target.value)}
                  className="w-full pl-10 pr-4 py-3 bg-white/10 border border-white/20 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 transition-all placeholder:text-slate-500"
                />
                <LinkIcon className="absolute left-3 top-3.5 w-4 h-4 text-slate-400" />
              </div>
              <button 
                onClick={handleUrlExtract}
                disabled={isExtracting || !propertyUrl}
                className="w-full bg-blue-600 hover:bg-blue-500 disabled:bg-slate-700 disabled:cursor-not-allowed text-white py-3 rounded-xl font-bold text-sm transition-all flex items-center justify-center gap-2 shadow-lg shadow-blue-900/20"
              >
                {isExtracting ? (
                  <>
                    <Loader2 className="w-4 h-4 animate-spin" />
                    解析中...
                  </>
                ) : (
                  <>
                    <Zap className="w-4 h-4 fill-current" />
                    物件情報を取得する
                  </>
                )}
              </button>
              {extractedSources.length > 0 && (
                <div className="mt-4 pt-3 border-t border-white/10">
                  <p className="text-[10px] font-bold text-slate-400 mb-2 uppercase tracking-wider">参照ソース:</p>
                  {extractedSources.map((src, idx) => (
                    <a key={idx} href={src.uri} target="_blank" rel="noopener noreferrer" className="flex items-center gap-1 text-[10px] text-blue-400 hover:underline truncate">
                      <ExternalLink size={10} />
                      {src.title}
                    </a>
                  ))}
                </div>
              )}
            </div>
          </section>

          {/* Daily Life / Income */}
          <section className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6">
            <div className="flex items-center gap-2 mb-6">
              <UserCheck className="w-5 h-5 text-emerald-600" />
              <h2 className="text-lg font-bold">家計・収入設定</h2>
            </div>
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-1">月々の手取り収入 (円)</label>
