                  type="number" name="monthlyTakeHomeIncome" value={inputs.monthlyTakeHomeIncome} onChange={handleInputChange}
                  className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 focus:outline-none transition-all"
                />
              </div>
              <div className={`p-4 rounded-xl border flex flex-col items-center justify-center transition-all ${getSustainabilityColor(results.housingCostRatio)}`}>
                <span className="text-xs font-bold uppercase mb-1 opacity-70">住居費負担率 (対手取り)</span>
                <span className="text-3xl font-black">{results.housingCostRatio.toFixed(1)}%</span>
                <span className="text-xs font-bold mt-1 uppercase tracking-wider">{getSustainabilityLabel(results.housingCostRatio)}</span>
              </div>
            </div>
          </section>

          {/* Property Parameters */}
          <section className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6">
            <div className="flex items-center gap-2 mb-6">
              <Calculator className="w-5 h-5 text-blue-600" />
              <h2 className="text-lg font-bold">物件・ローン詳細</h2>
            </div>

            <div className="space-y-4">
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-1">物件種別（税制優遇用）</label>
                <select 
                  name="buildingType" value={inputs.buildingType} onChange={handleInputChange}
                  className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 focus:outline-none transition-all text-sm font-medium"
