                  <option value="new_certified">新築・認定住宅 (減税上限4500万)</option>
                  <option value="new_standard">新築・一般住宅 (減税上限3000万)</option>
                  <option value="existing">中古住宅 (減税上限2000万)</option>
                </select>
              </div>

              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-1">物件購入価格 (円)</label>
                <input type="number" name="purchasePrice" value={inputs.purchasePrice} onChange={handleInputChange}
                  className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 focus:outline-none transition-all" />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-semibold text-slate-700 mb-1">頭金 (円)</label>
