                    className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg" />
                </div>
                <div>
                  <label className="block text-sm font-semibold text-slate-700 mb-1">借入金利 (%)</label>
                  <input type="number" step="0.01" name="interestRate" value={inputs.interestRate} onChange={handleInputChange}
                    className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg" />
                </div>
              </div>

              {/* Loan Term Selection */}
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-1 flex items-center gap-1">
                  <Clock className="w-3 h-3 text-blue-500" />
                  ローン期間 (年)
                </label>
                <div className="flex items-center gap-2">
                  <input 
                    type="range" name="mortgageTerm" min="1" max="50" step="1" 
                    value={inputs.mortgageTerm} onChange={handleInputChange} 
                    className="flex-1 h-1.5 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-blue-600" 
                  />
                  <input 
                    type="number" name="mortgageTerm" value={inputs.mortgageTerm} onChange={handleInputChange}
                    className="w-16 px-2 py-1 bg-slate-50 border border-slate-200 rounded text-center text-sm font-bold" 
                  />
                </div>
              </div>

              <div className="pt-4 border-t border-slate-100">
                <div className="flex items-center justify-between mb-2">
                   <label className="block text-sm font-semibold text-slate-700">固定資産税 (年額)</label>
                   <div className="flex items-center gap-2 px-2 py-1 bg-blue-50 rounded-md border border-blue-100 cursor-pointer" onClick={() => handleInputChange({target: {name: 'useAutoTax', checked: !inputs.useAutoTax, type: 'checkbox'}} as any)}>
                      <Zap className={`w-3 h-3 ${inputs.useAutoTax ? 'text-blue-600 fill-blue-600' : 'text-slate-400'}`} />
                      <span className="text-[10px] font-bold text-blue-800">自動算出</span>
                      <input type="checkbox" name="useAutoTax" checked={inputs.useAutoTax} onChange={handleInputChange} className="w-3 h-3 text-blue-600 rounded pointer-events-none" />
                   </div>
                </div>
                {inputs.useAutoTax ? (
                  <div className="space-y-2">
                    <div className="flex items-center justify-between px-4 py-2 bg-slate-100 rounded-lg border border-slate-200">
                      <span className="text-xs font-bold text-slate-500">概算見積額</span>
                      <span className="text-sm font-black text-slate-800">{formatCurrency(results.estimatedInitialTax)}</span>
                    </div>
                  </div>
                ) : (
                  <input type="number" name="fixedAssetTax" value={inputs.fixedAssetTax} onChange={handleInputChange}
                    className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500" />
                )}
              </div>

              {/* Selling Cost Auto-Calc Toggle */}
              <div className="pt-4 border-t border-slate-100">
                <div className="flex items-center justify-between mb-2">
                   <label className="block text-sm font-semibold text-slate-700">売却時諸経費</label>
                   <div className="flex items-center gap-2 px-2 py-1 bg-blue-50 rounded-md border border-blue-100 cursor-pointer" onClick={() => handleInputChange({target: {name: 'useAutoSellingCosts', checked: !inputs.useAutoSellingCosts, type: 'checkbox'}} as any)}>
                      <BadgeDollarSign className={`w-3 h-3 ${inputs.useAutoSellingCosts ? 'text-blue-600' : 'text-slate-400'}`} />
                      <span className="text-[10px] font-bold text-blue-800">自動試算</span>
                      <input type="checkbox" name="useAutoSellingCosts" checked={inputs.useAutoSellingCosts} onChange={handleInputChange} className="w-3 h-3 text-blue-600 rounded pointer-events-none" />
                   </div>
                </div>
                {inputs.useAutoSellingCosts ? (
                   <div className="flex items-center justify-between px-4 py-2 bg-slate-100 rounded-lg border border-slate-200">
                      <span className="text-xs font-bold text-slate-500">概算(3%+6万+税)</span>
                      <span className="text-sm font-black text-slate-800">{formatCurrency(results.sellingCosts)}</span>
                   </div>
                ) : (
                   <input type="number" name="manualSellingCosts" value={inputs.manualSellingCosts} onChange={handleInputChange}
                     className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500" />
                )}
              </div>

              <div className="pt-4 border-t border-slate-100 space-y-4">
                 <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="block text-sm font-semibold text-slate-700 mb-1">保有期間 (年)</label>
                      <input type="number" name="yearsHeld" value={inputs.yearsHeld} onChange={handleInputChange}
                        className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg" />
                    </div>
                    <div>
                      <label className="block text-sm font-semibold text-slate-700 mb-1">価格変動率 (%)</label>
                      <input type="number" step="0.1" name="appreciationRate" value={inputs.appreciationRate} onChange={handleInputChange}
                        className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg" />
                    </div>
                 </div>
              </div>
            </div>
          </section>

          <button onClick={runAiAnalysis} disabled={loadingAi} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold flex items-center justify-center gap-2 hover:bg-slate-800 transition-all shadow-lg disabled:opacity-50">
            {loadingAi ? <RefreshCcw className="w-5 h-5 animate-spin" /> : <BrainCircuit className="w-5 h-5" />}
            この条件でAIライフプラン診断
          </button>
        </aside>

        {/* Results Main Section */}
        <div className="lg:col-span-8 space-y-6">

          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm md:col-span-2">
              <p className="text-slate-500 text-xs font-bold uppercase tracking-wider mb-1">最終的な実質手残り益</p>
              <p className={`text-3xl font-black ${results.netProfit >= 0 ? 'text-emerald-600' : 'text-rose-600'}`}>
                {formatCurrency(results.netProfit)}
              </p>
              <div className="flex items-center gap-1 text-emerald-600 mt-2 text-xs font-bold">
                <Banknote className="w-3 h-3" />
                <span>内、ローン減税累計: {formatCurrency(results.totalMortgageTaxCredit)}</span>
              </div>
            </div>
            <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
              <p className="text-slate-500 text-xs font-bold uppercase tracking-wider mb-1">月々の住居費</p>
              <p className="text-xl font-black text-slate-800">{formatCurrency(results.monthlyHousingCost)}</p>
              <p className="text-xs text-slate-400 mt-1">残金: {formatCurrency(results.monthlySurplus)}</p>
            </div>
            <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
              <p className="text-slate-500 text-xs font-bold uppercase tracking-wider mb-1">売却予想額</p>
              <p className="text-xl font-black text-slate-800">{formatCurrency(results.sellingPrice)}</p>
              <p className="text-xs text-slate-400 mt-1">残債: {formatCurrency(results.remainingMortgageBalance)}</p>
            </div>
          </div>

          <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
            <div className="flex border-b border-slate-100 bg-slate-50/30">
              <button onClick={() => setActiveTab('summary')} className={`flex-1 py-4 px-6 text-sm font-bold transition-all ${activeTab === 'summary' ? 'text-blue-600 border-b-2 border-blue-600 bg-white' : 'text-slate-500 hover:bg-slate-50'}`}>
                収支詳細
              </button>
              <button onClick={() => setActiveTab('charts')} className={`flex-1 py-4 px-6 text-sm font-bold transition-all ${activeTab === 'charts' ? 'text-blue-600 border-b-2 border-blue-600 bg-white' : 'text-slate-500 hover:bg-slate-50'}`}>
                推移グラフ
              </button>
              <button onClick={() => setActiveTab('ai')} className={`flex-1 py-4 px-6 text-sm font-bold transition-all ${activeTab === 'ai' ? 'text-blue-600 border-b-2 border-blue-600 bg-white' : 'text-slate-500 hover:bg-slate-50'}`}>
                AI診断
              </button>
            </div>

            <div className="p-8">
              {activeTab === 'summary' && (
                <div className="space-y-12">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
                    <div className="space-y-6">
                      <h3 className="text-sm font-black text-slate-400 uppercase tracking-widest border-l-4 border-rose-500 pl-3">月々のキャッシュフロー</h3>
                      <div className="space-y-4">
                        <div className="flex justify-between text-slate-600">
                          <span>住宅ローン返済額</span>
                          <span className="font-semibold">{formatCurrency(results.totalMortgagePayments / (inputs.yearsHeld * 12))}</span>
                        </div>
                        <div className="flex justify-between text-slate-600">
                          <span>管理費・修繕積立金</span>
                          <span className="font-semibold">{formatCurrency(inputs.maintenanceFee + inputs.repairFund)}</span>
                        </div>
                        <div className="flex justify-between text-slate-600">
                          <span>固定資産税（月平均）</span>
                          <span className="font-semibold">{formatCurrency(results.estimatedInitialTax / 12)}</span>
                        </div>
                        <div className="flex justify-between text-slate-900 pt-3 border-t border-slate-100 font-bold">
                          <span>住居費合計</span>
                          <span className="text-rose-600">{formatCurrency(results.monthlyHousingCost)}</span>
                        </div>
                      </div>
                    </div>

                    <div className="space-y-6">
                      <h3 className="text-sm font-black text-slate-400 uppercase tracking-widest border-l-4 border-emerald-500 pl-3">売却時と税優遇</h3>
                      <div className="space-y-4">
                        <div className="flex justify-between text-emerald-600 font-bold">
                          <span>住宅ローン減税 (累計還付)</span>
                          <span>+{formatCurrency(results.totalMortgageTaxCredit)}</span>
                        </div>
                        <div className="flex justify-between text-slate-600">
                          <span>仲介手数料 (概算)</span>
                          <span className="font-semibold">-{formatCurrency(results.sellingBrokerageFee)}</span>
                        </div>
                        <div className="flex justify-between text-slate-600">
                          <span>印紙・登記等 (概算)</span>
                          <span className="font-semibold">-{formatCurrency(results.sellingOtherCosts)}</span>
                        </div>
                        <div className="flex justify-between text-rose-600">
                          <span>ローン返済・譲渡所得税</span>
                          <span className="font-semibold">-{formatCurrency(results.remainingMortgageBalance + results.taxAmount)}</span>
                        </div>
                        <div className="flex justify-between text-slate-900 pt-3 border-t border-slate-100 font-bold text-lg">
                          <span>売却時に手元に残る現金</span>
                          <span className="text-emerald-600">{formatCurrency(results.sellingPrice - results.remainingMortgageBalance - results.sellingCosts - results.taxAmount)}</span>
                        </div>
                      </div>
                    </div>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="bg-blue-50 p-6 rounded-2xl border border-blue-100 flex items-start gap-4">
                      <Zap className="w-5 h-5 text-blue-500 shrink-0 mt-1" />
                      <div>
                        <h4 className="text-sm font-bold text-blue-900 mb-2">固定資産税・売却費用の自動計算</h4>
                        <p className="text-xs text-blue-800 leading-relaxed">
                          固定資産税は小規模住宅用地の特例等を反映。売却費用は日本の商習慣（3%+6万+消費税）および標準的な登記費用を自動試算しています。
                        </p>
                      </div>
                    </div>
                    <div className="bg-emerald-50 p-6 rounded-2xl border border-emerald-100 flex items-start gap-4">
                      <Info className="w-5 h-5 text-emerald-500 shrink-0 mt-1" />
                      <div>
                        <h4 className="text-sm font-bold text-emerald-900 mb-2">住宅ローン減税の反映</h4>
                        <p className="text-xs text-emerald-800 leading-relaxed">
                          2024年現在の「年末ローン残高の0.7%を最大13年間還付」する制度に基づいています。
                        </p>
                      </div>
                    </div>
                  </div>
                </div>
              )}

              {activeTab === 'charts' && (
                <div className="space-y-12">
                  <div className="h-[350px]">
                    <h4 className="text-sm font-bold text-slate-700 mb-6 flex items-center gap-2">
                      <Activity className="w-4 h-4 text-blue-500" />
                      資産価値推移とローン残高
                    </h4>
                    <ResponsiveContainer width="100%" height="100%">
                      <AreaChart data={chartData}>
                        <defs>
                          <linearGradient id="colorVal" x1="0" y1="0" x2="0" y2="1">
                            <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.1}/>
                            <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                          </linearGradient>
                        </defs>
                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                        <XAxis dataKey="year" stroke="#94a3b8" fontSize={12} />
                        <YAxis stroke="#94a3b8" fontSize={12} />
                        <Tooltip contentStyle={{borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)'}} />
                        <Legend />
                        <Area type="monotone" dataKey="物件価値" stroke="#3b82f6" fill="url(#colorVal)" strokeWidth={3} />
                        <Line type="monotone" dataKey="ローン残高" stroke="#ef4444" strokeWidth={2} dot={false} />
                      </AreaChart>
                    </ResponsiveContainer>
                  </div>
                  <div className="h-[350px]">
                    <h4 className="text-sm font-bold text-slate-700 mb-6 flex items-center gap-2">
                      <Wallet className="w-4 h-4 text-emerald-500" />
                      支出と減税の推移
                    </h4>
                    <ResponsiveContainer width="100%" height="100%">
                      <BarChart data={chartData}>
                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                        <XAxis dataKey="year" stroke="#94a3b8" fontSize={12} />
                        <YAxis stroke="#94a3b8" fontSize={12} />
                        <Tooltip contentStyle={{borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)'}} />
                        <Legend />
                        <Bar dataKey="住宅ローン減税" fill="#10b981" stackId="a" radius={[4, 4, 0, 0]} />
                        <Bar dataKey="固定資産税" fill="#f59e0b" stackId="b" radius={[4, 4, 0, 0]} />
                      </BarChart>
                    </ResponsiveContainer>
                  </div>
                </div>
              )}

              {activeTab === 'ai' && (
                <div className="min-h-[400px]">
                  {loadingAi ? (
                    <div className="flex flex-col items-center justify-center h-full gap-4">
                      <RefreshCcw className="w-8 h-8 animate-spin text-blue-500" />
                      <p className="text-sm font-medium text-slate-500">家計状況と将来の資産性を分析中...</p>
                    </div>
                  ) : aiAdvice ? (
                    <div className="prose prose-slate max-w-none">
                      <div className="flex items-center gap-2 mb-6">
                        <ShieldCheck className="w-6 h-6 text-emerald-500" />
                        <h3 className="text-xl font-bold m-0 text-slate-800">AIライフプランニング診断レポート</h3>
                      </div>
                      <div className="bg-slate-50 p-8 rounded-3xl border border-slate-100 whitespace-pre-wrap leading-relaxed text-slate-700 font-medium shadow-inner">
                        {aiAdvice}
                      </div>
                    </div>
                  ) : (
                    <div className="flex flex-col items-center justify-center h-full text-slate-400 gap-4">
                      <div className="p-6 bg-slate-100 rounded-full">
                         <BrainCircuit className="w-12 h-12 opacity-40" />
                      </div>
                      <div className="text-center">
                         <p className="font-bold text-slate-600">AIアドバイザーが準備を整えています</p>
                         <p className="text-sm mt-1">「AIライフプラン診断」ボタンから詳細なレポートを生成できます</p>
                      </div>
                    </div>
                  )}
                </div>
              )}
            </div>
          </div>
        </div>
      </main>
    </div>
  );
};

export default App;

export type BuildingType = 'new_certified' | 'new_standard' | 'existing';

export interface SimulationInputs {
  purchasePrice: number;
  initialCosts: number; // 手動入力用
  useAutoInitialCosts: boolean; // 自動計算フラグ
  downPayment: number;
  mortgageTerm: number;
  interestRate: number;
  maintenanceFee: number;
  repairFund: number;
  fixedAssetTax: number; // 手動入力用
  useAutoTax: boolean;    // 固定資産税自動計算フラグ
  landRatio: number;      // 土地評価割合
  yearsHeld: number;
  appreciationRate: number;
  isPrimaryResidence: boolean;
  monthlyTakeHomeIncome: number;
  buildingType: BuildingType;
  useAutoSellingCosts: boolean;
  manualSellingCosts: number;
}

export interface SimulationResults {
  purchasePrice: number;
  initialTotalCost: number; // 合計諸経費
  initialBrokerageFee: number; // 内訳：仲介手数料
  initialOtherCosts: number;     // 内訳：登記・印紙・ローン手数料等
  sellingPrice: number;
  totalMaintenanceCosts: number;
  totalMortgagePayments: number;
  remainingMortgageBalance: number;
  sellingCosts: number;
  sellingBrokerageFee: number; 
  sellingOtherCosts: number;     
  taxAmount: number;
