export type BuildingType = 'new_certified' | 'new_standard' | 'existing';

export interface SimulationInputs {
  purchasePrice: number;
  initialCosts: number; // 手動入力用
  useAutoInitialCosts: boolean; // 自動計算フラグ
  downPayment: number;
  mortgageTerm: number;
