const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const getAIAnalysis = async (inputs: SimulationInputs, results: SimulationResults) => {
  const prompt = `
    あなたは不動産投資と住宅購入の専門アドバイザーです。以下のマンション購入シミュレーション結果を分析し、ユーザーに日本語で簡潔かつ論理的なアドバイスを提供してください。

    【購入条件】
    - 購入価格: ${inputs.purchasePrice}円
    - 保有期間: ${inputs.yearsHeld}年
    - 住宅ローン金利: ${inputs.interestRate}%
    - 年間資産価値変動率: ${inputs.appreciationRate}%

    【シミュレーション結果】
    - 最終売却価格予想: ${results.sellingPrice}円
    - 実質総支出: ${results.totalOutflow}円
    - 最終的な純損益: ${results.netProfit}円
    - ローン残債: ${results.remainingMortgageBalance}円
    - 住宅ローン減税累計: ${results.totalMortgageTaxCredit}円

    以下の観点を含めてください：
    1. この計画の経済的合理性（得か損か）
    2. 最大のリスク要因（特に家計の負担率 ${results.housingCostRatio.toFixed(1)}% について）
    3. 改善のための提案（売却時期、繰り上げ返済、物件選びのポイントなど）
    4. 市場環境への言及
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
    });
    return { text: response.text };
  } catch (error) {
    console.error("Gemini Error:", error);
    return { text: "AIによる分析中にエラーが発生しました。" };
  }
};

export const extractPropertyFromUrl = async (url: string) => {
  const prompt = `
    以下の不動産物件URL（SUUMO等）の内容を読み取り、シミュレーションに必要な項目を抽出してください。
    URL: ${url}

    抽出項目:
    - 物件価格 (purchasePrice): 円単位の数値
    - 管理費 (maintenanceFee): 月額、数値
    - 修繕積立金 (repairFund): 月額、数値
    - 物件種別 (buildingType): 'new_certified' (新築・認定), 'new_standard' (新築・一般), 'existing' (中古) のいずれか。判断がつかない場合は 'existing'。
    - 土地権利割合 (landRatio): パーセント数値。不明なら 20。
    - 物件の住所 (propertyAddress): 文字列
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            purchasePrice: { type: Type.NUMBER },
            maintenanceFee: { type: Type.NUMBER },
            repairFund: { type: Type.NUMBER },
            buildingType: { type: Type.STRING },
            landRatio: { type: Type.NUMBER },
            propertyName: { type: Type.STRING },
            propertyAddress: { type: Type.STRING },
          },
          required: ["purchasePrice", "maintenanceFee", "repairFund", "buildingType", "propertyAddress"]
        }
      }
    });

    const data = JSON.parse(response.text);
    const sources = response.candidates?.[0]?.groundingMetadata?.groundingChunks?.map(chunk => ({
      title: chunk.web?.title || "参照元",
      uri: chunk.web?.uri || ""
    })) || [];

    return { data, sources };
  } catch (error) {
    console.error("Extraction Error:", error);
    throw new Error("物件情報の取得に失敗しました。URLが正しいか確認してください。");
  }
};

export const getCommuteInfo = async (origin: string, destination: string) => {
  const prompt = `住所「${origin}」から「${destination}」まで、公共交通機関を利用して最短ルートで何分かかるか教えてください。具体的なルートと所要時間を含めて回答してください。`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
      config: {
        tools: [{ googleMaps: {} }],
      },
    });

    const text = response.text || "情報を取得できませんでした。";
    const mapsChunk = response.candidates?.[0]?.groundingMetadata?.groundingChunks?.find(chunk => chunk.maps?.uri);
    const mapsUrl = mapsChunk?.maps?.uri || `https://www.google.com/maps/dir/${encodeURIComponent(origin)}/${encodeURIComponent(destination)}`;

    return { text, mapsUrl };
  } catch (error) {
    console.error("Maps Error:", error);
    return { text: "ルート検索中にエラーが発生しました。住所が正しいか確認してください。", mapsUrl: "" };
  }
};

