    setLoadingCommute(true);
    const info = await getCommuteInfo(inputs.propertyAddress, inputs.targetStation);
    setCommuteResult(info);
    setLoadingCommute(false);
  };

  const runAiAnalysis = async () => {
    setLoadingAi(true);
    const advice = await getAIAnalysis(inputs, results);
    setAiAdvice(advice.text);
    setLoadingAi(false);
    setActiveTab('ai');
