  const [results, setResults] = useState<SimulationResults>(calculateSimulation(INITIAL_VALUES));
  const [aiAdvice, setAiAdvice] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);
  const [activeTab, setActiveTab] = useState<'summary' | 'charts' | 'ai'>('summary');

  // URL Import States
  const [propertyUrl, setPropertyUrl] = useState('');
  const [isExtracting, setIsExtracting] = useState(false);
  const [extractedSources, setExtractedSources] = useState<{title: string, uri: string}[]>([]);

  // Commute States
  const [commuteResult, setCommuteResult] = useState<{ text: string, mapsUrl: string } | null>(null);
  const [loadingCommute, setLoadingCommute] = useState(false);

  useEffect(() => {
    setResults(calculateSimulation(inputs));
  }, [inputs]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target;
    const checked = (e.target as HTMLInputElement).checked;

    setInputs(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : 
              (name === 'buildingType' ? value : (parseFloat(value) || 0))
    }));
  };

  const handleManualInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setInputs(prev => ({ ...prev, [name]: value }));
  };

  const handleUrlExtract = async () => {
    if (!propertyUrl) return;
    setIsExtracting(true);
    try {
      const { data, sources } = await extractPropertyFromUrl(propertyUrl);
      setInputs(prev => ({
        ...prev,
        purchasePrice: data.purchasePrice || prev.purchasePrice,
        maintenanceFee: data.maintenanceFee || prev.maintenanceFee,
        repairFund: data.repairFund || prev.repairFund,
        buildingType: (data.buildingType as BuildingType) || prev.buildingType,
        landRatio: data.landRatio || prev.landRatio,
        propertyAddress: data.propertyAddress || prev.propertyAddress,
      }));
      setExtractedSources(sources);
      alert(`${data.propertyName || '物件'} の情報を取得・反映しました。`);
    } catch (error: any) {
      alert(error.message);
    } finally {
      setIsExtracting(false);
    }
  };

  const handleCommuteSearch = async () => {
    if (!inputs.propertyAddress || !inputs.targetStation) {
      alert("物件の住所と目的の駅を入力してください。");
      return;
    }
    setLoadingCommute(true);
    const info = await getCommuteInfo(inputs.propertyAddress, inputs.targetStation);
    setCommuteResult(info);
    setLoadingCommute(false);
  };

  const runAiAnalysis = async () => {
    setLoadingAi(true);
    const advice = await getAIAnalysis(inputs, results);
    setAiAdvice(advice.text);
    setLoadingAi(false);
    setActiveTab('ai');
  };

  const chartData = useMemo(() => {
    return results.yearlyData.map(d => ({
      year: `${d.year}年目`,
      "購入累計実質負担": Math.round(d.cumulativeCost / 10000) / 100,
      "賃貸累計支払い": Math.round(d.cumulativeRentalCost / 10000) / 100,
      "物件価値": Math.round(d.propertyValue / 10000) / 100,
      "ローン残高": Math.round(d.mortgageBalance / 10000) / 100,
    }));
  }, [results]);

  const barData = [
    { name: '投下資本 (総計)', value: Math.round((inputs.downPayment + results.initialTotalCost + results.totalMortgagePayments + results.totalMaintenanceCosts - results.totalMortgageTaxCredit) / 10000) },
    { name: '回収資金 (手残り)', value: Math.round((results.sellingPrice - results.remainingMortgageBalance - results.sellingCosts - results.taxAmount) / 10000) }
  ];

  return (
    <div className="min-h-screen bg-slate-50 pb-20 font-['Inter','Noto_Sans_JP']">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-50 shadow-sm">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="bg-slate-900 p-1.5 rounded-lg">
              <TrendingUp className="text-white w-6 h-6" />
            </div>
            <h1 className="text-xl font-bold text-slate-800 tracking-tight">Condo Wealth <span className="text-blue-600">Pro</span></h1>
          </div>
          <div className="flex items-center gap-4 text-sm text-slate-500 font-medium">
            <button onClick={() => {setInputs(INITIAL_VALUES); setExtractedSources([]); setPropertyUrl(''); setCommuteResult(null);}} className="flex items-center gap-1 hover:text-blue-600 transition-colors">
              <RefreshCcw className="w-4 h-4" /> リセット
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 mt-8 grid grid-cols-1 lg:grid-cols-12 gap-8">

        {/* Input Sidebar */}
        <aside className="lg:col-span-4 space-y-6">

          {/* AI URL Import Section */}
          <section className="bg-gradient-to-br from-slate-800 to-slate-900 rounded-2xl shadow-lg p-6 text-white overflow-hidden relative border border-slate-700">
            <div className="absolute top-0 right-0 p-4 opacity-10 pointer-events-none">
               <LinkIcon size={80} />
            </div>
            <div className="flex items-center gap-2 mb-4 relative z-10">
              <BrainCircuit className="w-5 h-5 text-blue-400" />
              <h2 className="text-lg font-bold">AI物件データ取得</h2>
            </div>
            <p className="text-xs text-slate-300 mb-4 leading-relaxed font-medium">
              URLを貼るだけで価格や住所を自動入力します。
            </p>
            <div className="space-y-3 relative z-10">
              <input 
                type="text" 
                placeholder="https://suumo.jp/..." 
                value={propertyUrl}
                onChange={(e) => setPropertyUrl(e.target.value)}
                className="w-full pl-4 pr-4 py-3 bg-white/10 border border-white/20 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 transition-all placeholder:text-slate-500"
              />
              <button 
                onClick={handleUrlExtract}
                disabled={isExtracting || !propertyUrl}
                className="w-full bg-blue-600 hover:bg-blue-500 disabled:bg-slate-700 disabled:cursor-not-allowed text-white py-3 rounded-xl font-bold text-sm transition-all flex items-center justify-center gap-2 shadow-lg shadow-blue-900/20"
              >
                {isExtracting ? <Loader2 className="w-4 h-4 animate-spin" /> : <Zap className="w-4 h-4 fill-current" />}
                物件情報を解析
              </button>
            </div>
          </section>

          {/* Main Simulation Parameters */}
          <section className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6">
            <div className="flex items-center gap-2 mb-6">
              <Calculator className="w-5 h-5 text-blue-600" />
              <h2 className="text-lg font-bold">売却シミュレーション条件</h2>
            </div>
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="col-span-2">
                  <label className="block text-sm font-semibold text-slate-700 mb-1">物件購入価格 (円)</label>
                  <input type="number" name="purchasePrice" value={inputs.purchasePrice} onChange={handleInputChange}
                    className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg font-black text-lg text-blue-600" />
                </div>
                <div>
                  <label className="block text-sm font-semibold text-slate-700 mb-1">頭金 (円)</label>
                  <input type="number" name="downPayment" value={inputs.downPayment} onChange={handleInputChange}
                    className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg font-bold" />
                </div>
                <div>
                  <label className="block text-sm font-semibold text-slate-700 mb-1">住宅ローン金利 (%)</label>
                  <input type="number" step="0.01" name="interestRate" value={inputs.interestRate} onChange={handleInputChange}
                    className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg font-bold" />
                </div>
              </div>
              <div className="pt-4 border-t border-slate-100 flex justify-between gap-4">
                <div className="flex-1">
                   <label className="block text-sm font-semibold text-slate-700 flex items-center gap-1">
                      <Clock className="w-3 h-3 text-blue-500" /> 
                      保有期間 (年)
                   </label>
                   <input type="number" name="yearsHeld" value={inputs.yearsHeld} onChange={handleInputChange}
                        className="w-full px-2 py-1 bg-blue-50 border border-blue-200 rounded-lg text-center font-black text-blue-700" />
                </div>
                <div className="flex-1">
                   <label className="block text-sm font-semibold text-slate-700 flex items-center gap-1">
                      <TrendingUp className="w-3 h-3 text-emerald-500" />
                      価格変動率 (%)
                   </label>
                   <input type="number" step="0.1" name="appreciationRate" value={inputs.appreciationRate} onChange={handleInputChange}
                        className="w-full px-2 py-1 bg-emerald-50 border border-emerald-200 rounded-lg text-center font-black text-emerald-700" />
                </div>
              </div>
            </div>
          </section>

          {/* Rental (Bonus) Parameter */}
          <section className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6">
            <div className="flex items-center justify-between mb-4">
              <div className="flex items-center gap-2">
                <Home className="w-5 h-5 text-slate-400" />
                <h2 className="text-sm font-bold text-slate-500">賃貸比較（参考）</h2>
              </div>
              <button 
                className={`flex items-center gap-1.5 px-2 py-1 rounded border text-[9px] font-bold transition-all ${inputs.useAutoRent ? 'bg-slate-800 border-slate-800 text-white' : 'bg-white border-slate-200 text-slate-400'}`}
                onClick={() => handleInputChange({target: {name: 'useAutoRent', checked: !inputs.useAutoRent, type: 'checkbox'}} as any)}
              >
                自動算出 {inputs.useAutoRent ? 'ON' : 'OFF'}
              </button>
            </div>
            {inputs.useAutoRent ? (
                <div className="px-3 py-2 bg-slate-50 border border-slate-100 rounded-lg flex justify-between items-center">
                  <span className="text-[10px] text-slate-400">想定賃料</span>
                  <span className="text-sm font-bold text-slate-600">{formatCurrency(results.estimatedMonthlyRent)}</span>
                </div>
            ) : (
                <div className="relative">
                  <input 
                    type="number" name="estimatedMonthlyRent" value={inputs.estimatedMonthlyRent} onChange={handleInputChange}
                    className="w-full px-3 py-2 bg-white border border-slate-200 rounded-lg text-sm font-bold text-slate-600"
                  />
                  <span className="absolute right-3 top-1/2 -translate-y-1/2 text-xs text-slate-400">円</span>
                </div>
            )}
          </section>

          <button onClick={runAiAnalysis} disabled={loadingAi} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold flex items-center justify-center gap-2 hover:bg-slate-800 transition-all shadow-lg disabled:opacity-50">
            {loadingAi ? <RefreshCcw className="w-5 h-5 animate-spin" /> : <BrainCircuit className="w-5 h-5" />}
            AI売却収支アドバイス
          </button>
        </aside>

        {/* Results Main Section */}
        <div className="lg:col-span-8 space-y-6">

          {/* Main Selling KPI */}
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            <div className="bg-white p-6 rounded-3xl border-2 border-slate-900 shadow-xl md:col-span-2 relative overflow-hidden ring-4 ring-blue-50">
              <div className="absolute top-0 right-0 p-4 opacity-5 pointer-events-none">
                <BadgeDollarSign size={100} />
              </div>
              <div className="flex items-center gap-2 mb-2">
                <span className="bg-slate-900 text-white text-[10px] font-black px-2 py-0.5 rounded uppercase tracking-tighter">Net Profit</span>
                <p className="text-slate-500 text-xs font-black uppercase tracking-widest">{inputs.yearsHeld}年後のトータル純損益</p>
              </div>
              <p className={`text-4xl font-black ${results.netProfit >= 0 ? 'text-emerald-600' : 'text-rose-600'}`}>
                {results.netProfit >= 0 ? '+' : ''}{formatCurrency(results.netProfit)}
              </p>
              <div className="mt-4 flex items-center gap-2">
                 <div className="flex-1 h-2 bg-slate-100 rounded-full overflow-hidden">
                    <div 
                      className={`h-full ${results.netProfit >= 0 ? 'bg-emerald-500' : 'bg-rose-500'}`} 
                      style={{width: results.netProfit >= 0 ? '100%' : '30%'}}
                    />
                 </div>
                 <span className="text-[10px] font-bold text-slate-400 whitespace-nowrap">
                   {results.netProfit >= 0 ? '資産価値 > 支出' : '資産価値 < 支出'}
                 </span>
              </div>
            </div>
            <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm text-center">
              <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest mb-1">売却時手元現金</p>
              <p className="text-2xl font-black text-slate-800">
                {formatCurrency(results.sellingPrice - results.remainingMortgageBalance - results.sellingCosts - results.taxAmount)}
              </p>
              <p className="text-[10px] text-slate-400 mt-1 font-bold">ローン精算・諸経費込</p>
            </div>
            <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm text-center">
              <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest mb-1">月々の実質住居費</p>
              <p className="text-2xl font-black text-slate-800">{formatCurrency(results.monthlyHousingCost)}</p>
              <p className="text-[10px] text-slate-400 mt-1 font-bold">維持費・減税非考慮</p>
            </div>
          </div>

          <div className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
            <div className="flex border-b border-slate-100 bg-slate-50/30">
              <button onClick={() => setActiveTab('summary')} className={`flex-1 py-4 px-6 text-sm font-black transition-all ${activeTab === 'summary' ? 'text-slate-900 border-b-4 border-slate-900 bg-white' : 'text-slate-400 hover:bg-slate-50'}`}>
                売却シミュレーション詳細
              </button>
              <button onClick={() => setActiveTab('charts')} className={`flex-1 py-4 px-6 text-sm font-black transition-all ${activeTab === 'charts' ? 'text-slate-900 border-b-4 border-slate-900 bg-white' : 'text-slate-400 hover:bg-slate-50'}`}>
                資産価値推移
              </button>
              <button onClick={() => setActiveTab('ai')} className={`flex-1 py-4 px-6 text-sm font-black transition-all ${activeTab === 'ai' ? 'text-slate-900 border-b-4 border-slate-900 bg-white' : 'text-slate-400 hover:bg-slate-50'}`}>
                AI詳細レポート
              </button>
            </div>

            <div className="p-8">
              {activeTab === 'summary' && (
                <div className="space-y-12">

                  {/* Selling Breakdown Section */}
                  <div className="space-y-6">
                    <div className="flex items-center gap-3">
                       <Scale className="w-6 h-6 text-slate-800" />
                       <h3 className="text-xl font-black text-slate-800">10年間のキャッシュフロー詳細</h3>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                      {/* Left Side: Cash Out */}
                      <div className="bg-slate-50 rounded-3xl p-6 border border-slate-200 space-y-6">
                        <div className="flex items-center gap-2 text-rose-600 font-black text-sm uppercase">
                          <ArrowDownCircle size={18} />
                          投下資本（全期間の総支払い）
                        </div>
                        <div className="space-y-4">
                          <div className="flex justify-between items-center text-sm">
                            <span className="text-slate-500">頭金 + 購入諸経費</span>
                            <span className="font-bold text-slate-800">{formatCurrency(inputs.downPayment + results.initialTotalCost)}</span>
                          </div>
                          <div className="flex justify-between items-center text-sm">
                            <span className="text-slate-500">住宅ローン返済累計</span>
                            <span className="font-bold text-slate-800">{formatCurrency(results.totalMortgagePayments)}</span>
                          </div>
                          <div className="flex justify-between items-center text-sm">
                            <span className="text-slate-500">管理費・修繕費・固定資産税累計</span>
                            <span className="font-bold text-slate-800">{formatCurrency(results.totalMaintenanceCosts)}</span>
                          </div>
                          <div className="flex justify-between items-center text-sm text-emerald-600 bg-white p-2 rounded-lg border border-emerald-100">
                            <span className="font-bold">住宅ローン控除還付累計</span>
                            <span className="font-black">- {formatCurrency(results.totalMortgageTaxCredit)}</span>
                          </div>
                          <div className="pt-4 border-t border-slate-200 flex justify-between items-center">
                            <span className="text-xs font-black text-slate-400 uppercase">実質総投資額 (Cash Out)</span>
                            <span className="text-xl font-black text-rose-700">{formatCurrency(results.totalOutflow - results.remainingMortgageBalance - results.sellingCosts - results.taxAmount)}</span>
                          </div>
                        </div>
                      </div>

                      {/* Right Side: Cash In */}
                      <div className="bg-blue-50/50 rounded-3xl p-6 border border-blue-100 space-y-6">
                        <div className="flex items-center gap-2 text-blue-600 font-black text-sm uppercase">
                          <ArrowUpCircle size={18} />
                          回収資金（売却時の手元現金）
                        </div>
                        <div className="space-y-4">
                          <div className="flex justify-between items-center text-sm">
                            <span className="text-slate-500">予想売却価格</span>
                            <span className="font-bold text-slate-800">{formatCurrency(results.sellingPrice)}</span>
                          </div>
                          <div className="flex justify-between items-center text-sm text-rose-500">
                            <span>ローン一括返済残額</span>
                            <span className="font-bold">- {formatCurrency(results.remainingMortgageBalance)}</span>
                          </div>
                          <div className="flex justify-between items-center text-sm text-rose-500">
                            <span>売却時諸経費 + 譲渡所得税</span>
                            <span className="font-bold">- {formatCurrency(results.sellingCosts + results.taxAmount)}</span>
                          </div>
                          <div className="pt-12 border-t border-blue-200 flex justify-between items-center">
                            <span className="text-xs font-black text-slate-400 uppercase">最終手元現金 (Cash In)</span>
                            <span className="text-xl font-black text-blue-700">{formatCurrency(results.sellingPrice - results.remainingMortgageBalance - results.sellingCosts - results.taxAmount)}</span>
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>

                  {/* Summary Visual Chart */}
                  <div className="bg-slate-900 rounded-[2.5rem] p-10 text-white shadow-2xl relative overflow-hidden">
                    <div className="absolute top-0 right-0 w-64 h-64 bg-blue-600/20 rounded-full blur-3xl -mr-32 -mt-32"></div>
                    <div className="flex flex-col md:flex-row items-center gap-12">
                       <div className="w-full md:w-1/2 h-[300px]">
                          <ResponsiveContainer width="100%" height="100%">
                            <BarChart data={barData} layout="vertical">
                              <XAxis type="number" hide />
                              <YAxis dataKey="name" type="category" stroke="#94a3b8" fontSize={10} width={100} />
                              <Tooltip cursor={{fill: 'transparent'}} contentStyle={{backgroundColor: '#1e293b', border: 'none', color: '#fff'}} />
                              <Bar dataKey="value" radius={[0, 10, 10, 0]} barSize={40}>
                                 {barData.map((entry, index) => (
                                    <Cell key={`cell-${index}`} fill={index === 0 ? '#f43f5e' : '#3b82f6'} />
                                 ))}
                              </Bar>
                            </BarChart>
                          </ResponsiveContainer>
                       </div>
                       <div className="w-full md:w-1/2 space-y-4">
                          <p className="text-blue-400 text-xs font-black uppercase tracking-widest">Simulation Result</p>
