                    ) : (
                      <p className="text-slate-400 italic">周辺エリアの将来的な価値を、現在の先輩物件から予測します。</p>
                    )}
                  </div>
               </div>
            </div>

          </div>
        </div>
      </main>
    </div>
  );
};

export default App;

