                    </div>
                    {loadingHazard && <Loader2 className="w-4 h-4 animate-spin text-blue-500" />}
                  </div>
                  <div className="text-sm leading-relaxed text-slate-600 bg-slate-50 p-6 rounded-2xl border border-slate-100 min-h-[150px]">
