                              {hazardInfo.sources.map((s, i) => (
                                <a key={i} href={s.uri} target="_blank" rel="noopener noreferrer" className="flex items-center gap-1 text-[10px] bg-white px-2 py-1 rounded border border-slate-200 text-blue-600 hover:bg-blue-50 transition-colors">
                                  <ExternalLink size={10} /> {s.title}
