                              ))}
                            </div>
                          </div>
                        )}
                      </div>
                    ) : (
                      <p className="text-slate-400 italic">住所を入力して、土地の安全性を確認しましょう。</p>
                    )}
                  </div>
               </div>

               {/* Column 2: Exit Strategy Verification (Local Market Data) */}
               <div className="bg-white rounded-3xl p-8 border border-slate-200 shadow-sm space-y-6">
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-3">
                       <History className="w-6 h-6 text-amber-500" />
                       <h3 className="text-lg font-black text-slate-800">出口戦略（{inputs.yearsHeld}年後の世界）</h3>
                    </div>
                    {loadingExit && <Loader2 className="w-4 h-4 animate-spin text-amber-500" />}
                  </div>
                  <div className="text-sm leading-relaxed text-slate-600 bg-slate-50 p-6 rounded-2xl border border-slate-100 min-h-[150px]">
                    {exitStrategy ? (
                      <div className="space-y-4">
                        <p className="whitespace-pre-wrap">{exitStrategy.text}</p>
                        {exitStrategy.sources.length > 0 && (
                          <div className="pt-4 border-t border-slate-200">
                            <p className="text-[10px] font-black text-slate-400 mb-2 uppercase tracking-widest">実際の周辺相場ソース</p>
                            <div className="flex flex-wrap gap-2">
                              {exitStrategy.sources.map((s, i) => (
                                <a key={i} href={s.uri} target="_blank" rel="noopener noreferrer" className="flex items-center gap-1 text-[10px] bg-white px-2 py-1 rounded border border-slate-200 text-amber-600 hover:bg-amber-50 transition-colors">
                                  <ExternalLink size={10} /> {s.title}
                                </a>
                              ))}
                            </div>
                          </div>
                        )}
                      </div>
                    ) : (
                      <p className="text-slate-400 italic">周辺エリアの将来的な価値を、現在の先輩物件から予測します。</p>
                    )}
                  </div>
               </div>
            </div>

          </div>
        </div>
      </main>
    </div>
  );
};

export default App;

