  const realSellingCashIn = results.sellingPrice - results.remainingMortgageBalance - results.sellingCosts - results.taxAmount;

  const monthlyPieData = [
    { name: 'ローン', value: results.monthlyMortgagePayment, fill: '#3b82f6' },
    { name: '管理費', value: results.monthlyMaintenanceFee, fill: '#6366f1' },
    { name: '修繕金', value: results.monthlyRepairFund, fill: '#8b5cf6' },
    { name: '固定資産税', value: results.estimatedInitialFixedAssetTax / 12, fill: '#f43f5e' },
