const App: React.FC = () => {
  const [inputs, setInputs] = useState<SimulationInputs>(INITIAL_VALUES);
  const [results, setResults] = useState<SimulationResults>(calculateSimulation(INITIAL_VALUES));
  const [aiAdvice, setAiAdvice] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);
  const [activeTab, setActiveTab] = useState<'summary' | 'charts' | 'ai'>('summary');

  // Analytical States
  const [hazardInfo, setHazardInfo] = useState<{ text: string, sources: {title: string, uri: string}[] } | null>(null);
  const [loadingHazard, setLoadingHazard] = useState(false);
  const [exitStrategy, setExitStrategy] = useState<{ text: string, sources: {title: string, uri: string}[] } | null>(null);
  const [loadingExit, setLoadingExit] = useState(false);

  // URL Import States
  const [propertyUrl, setPropertyUrl] = useState('');
  const [isExtracting, setIsExtracting] = useState(false);
  const [extractedSources, setExtractedSources] = useState<{title: string, uri: string}[]>([]);

  useEffect(() => {
    setResults(calculateSimulation(inputs));
  }, [inputs]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target;
    const checked = (e.target as HTMLInputElement).checked;

    setInputs(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : 
              (name === 'buildingType' ? value : (parseFloat(value) || 0))
    }));
  };

  const handleUrlExtract = async () => {
    if (!propertyUrl) return;
    setIsExtracting(true);
    try {
      const { data, sources } = await extractPropertyFromUrl(propertyUrl);
      setInputs(prev => ({
        ...prev,
        purchasePrice: data.purchasePrice || prev.purchasePrice,
        maintenanceFee: data.maintenanceFee || prev.maintenanceFee,
        repairFund: data.repairFund || prev.repairFund,
        buildingType: (data.buildingType as BuildingType) || prev.buildingType,
        landRatio: data.landRatio || prev.landRatio,
        propertyAddress: data.propertyAddress || prev.propertyAddress,
      }));
      setExtractedSources(sources);
      if (data.propertyAddress) {
        fetchLocationAnalysis(data.propertyAddress);
      }
    } catch (error: any) {
      alert(error.message);
    } finally {
      setIsExtracting(false);
    }
  };

  const fetchLocationAnalysis = async (address: string) => {
    setLoadingHazard(true);
    setLoadingExit(true);
    const [hazard, exit] = await Promise.all([
      getHazardAnalysis(address),
      getExitStrategyData(address, inputs.yearsHeld)
    ]);
    setHazardInfo(hazard);
    setExitStrategy(exit);
    setLoadingHazard(false);
    setLoadingExit(false);
  };

  const handleManualAddressAnalysis = () => {
    if (!inputs.propertyAddress) {
      alert("物件の住所を入力してください。");
      return;
    }
    fetchLocationAnalysis(inputs.propertyAddress);
  };

  const runAiAnalysis = async () => {
    setLoadingAi(true);
    const advice = await getAIAnalysis(inputs, results);
    setAiAdvice(advice.text);
    setLoadingAi(false);
    setActiveTab('ai');
  };

  const realSellingCashIn = results.sellingPrice - results.remainingMortgageBalance - results.sellingCosts - results.taxAmount;

  // 実質月額コストの計算
  const totalMonths = inputs.yearsHeld * 12;
  const buyRealMonthlyCost = results.netProfit >= 0 ? 0 : Math.abs(results.netProfit) / totalMonths;
  const rentRealMonthlyCost = results.totalRentalCost / totalMonths;
  const monthlyAdvantage = rentRealMonthlyCost - buyRealMonthlyCost;

  // 譲渡所得の簡易計算表示用
  const estimatedCapitalGain = results.sellingPrice - (inputs.purchasePrice + results.initialTotalCost) - results.sellingCosts;

  return (
