          </div>
          <div className="flex items-center gap-4 text-sm text-slate-500 font-medium">
            <button onClick={() => {setInputs(INITIAL_VALUES); setHazardInfo(null); setExitStrategy(null);}} className="flex items-center gap-1 hover:text-blue-600 transition-colors">
              <RefreshCcw className="w-4 h-4" /> リセット
            </button>
          </div>
