              <div className="flex items-center gap-2 mb-4 relative z-10">
                <BrainCircuit className="w-5 h-5 text-blue-400" />
                <h2 className="text-lg font-bold">AI物件データ取得</h2>
              </div>
              <div className="space-y-3 relative z-10">
                <input 
                  type="text" placeholder="https://suumo.jp/..." value={propertyUrl} onChange={(e) => setPropertyUrl(e.target.value)}
                  className="w-full pl-4 pr-4 py-3 bg-white/10 border border-white/20 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 placeholder:text-slate-500"
                />
                <button onClick={handleUrlExtract} disabled={isExtracting || !propertyUrl} className="w-full bg-blue-600 hover:bg-blue-500 disabled:bg-slate-700 text-white py-3 rounded-xl font-bold text-sm transition-all flex items-center justify-center gap-2">
