                </button>
              </div>
            </section>

            <section className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6">
              <div className="flex items-center gap-2 mb-6">
                <Calculator className="w-5 h-5 text-blue-600" /><h2 className="text-lg font-bold">シミュレーション条件</h2>
              </div>
              <div className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div className="col-span-2">
                    <label className="block text-sm font-semibold text-slate-700 mb-1">物件住所</label>
                    <div className="flex gap-2">
                      <input type="text" name="propertyAddress" value={inputs.propertyAddress} onChange={(e) => setInputs({...inputs, propertyAddress: e.target.value})}
                        placeholder="東京都港区..." className="flex-1 px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm font-medium" />
                      <button onClick={handleManualAddressAnalysis} className="p-2 bg-slate-100 hover:bg-slate-200 rounded-lg text-slate-600" title="住所からハザード・相場を再取得">
                        <Search size={18} />
                      </button>
                    </div>
                  </div>
                  <div className="col-span-2">
                    <label className="block text-sm font-semibold text-slate-700 mb-1">物件購入価格 (円)</label>
                    <input type="number" name="purchasePrice" value={inputs.purchasePrice} onChange={handleInputChange} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg font-black text-lg text-blue-600" />
                  </div>
                  <div className="col-span-2">
                    <label className="block text-sm font-semibold text-slate-700 mb-1">手取り月収 (円)</label>
                    <input type="number" name="monthlyTakeHomeIncome" value={inputs.monthlyTakeHomeIncome} onChange={handleInputChange} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg font-bold" />
                  </div>
