                  <div><label className="block text-sm font-semibold text-slate-700 mb-1">修繕積立金 (月額)</label><input type="number" name="repairFund" value={inputs.repairFund} onChange={handleInputChange} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg" /></div>
