const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * ユーティリティ: テキストからJSONブロックを抽出してパースする
 */
const parseJsonFromText = (text: string) => {
  try {
    // まず直接パースを試みる
    return JSON.parse(text);
  } catch {
    try {
      // Markdownのコードブロックを探す
      const jsonMatch = text.match(/```json\n?([\s\S]*?)\n?```/) || text.match(/```\n?([\s\S]*?)\n?```/);
      if (jsonMatch && jsonMatch[1]) {
        return JSON.parse(jsonMatch[1].trim());
      }
      // 強引に { } の間を抜粋する（最後の手段）
      const firstBrace = text.indexOf('{');
      const lastBrace = text.lastIndexOf('}');
      if (firstBrace !== -1 && lastBrace !== -1) {
        return JSON.parse(text.substring(firstBrace, lastBrace + 1));
      }
    } catch (e) {
      console.error("JSON parsing failed:", e);
    }
  }
  return null;
};

export const getAIAnalysis = async (inputs: SimulationInputs, results: SimulationResults) => {
  const prompt = `
    あなたは不動産投資と住宅購入の専門アドバイザーです。以下のマンション購入シミュレーション結果を分析し、ユーザーに日本語で簡潔かつ論理的なアドバイスを提供してください。

    【購入条件】
    - 購入価格: ${inputs.purchasePrice}円
    - 保有期間: ${inputs.yearsHeld}年
    - 住宅ローン金利: ${inputs.interestRate}%
    - 年間資産価値変動率: ${inputs.appreciationRate}%

    【シミュレーション結果】
    - 最終売却価格予想: ${results.sellingPrice}円
    - 実質総支出: ${results.totalOutflow}円
    - 最終的な純損益: ${results.netProfit}円
    - ローン残債: ${results.remainingMortgageBalance}円
    - 住宅ローン減税累計: ${results.totalMortgageTaxCredit}円

    以下の観点を含めてください：
    1. この計画の経済的合理性（得か損か）
    2. 最大のリスク要因（特に家計の負担率 ${results.housingCostRatio.toFixed(1)}% について）
    3. 改善のための提案（売却時期、繰り上げ返済、物件選びのポイントなど）
    4. 市場環境への言及
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
    });
    return { text: response.text };
  } catch (error) {
    console.error("Gemini Error:", error);
    return { text: "AIによる分析中にエラーが発生しました。" };
  }
};

export const extractPropertyFromUrl = async (url: string) => {
  const prompt = `
    以下の不動産物件URLの内容をGoogle検索等を用いて読み取り、シミュレーションに必要な項目を抽出してJSON形式で回答してください。
    URL: ${url}

    JSONのキー:
    - purchasePrice: 物件価格（数値、円単位）
    - maintenanceFee: 管理費（数値、月額）
    - repairFund: 修繕積立金（数値、月額）
    - buildingType: 'new_certified' (新築・認定), 'new_standard' (新築・一般), 'existing' (中古) のいずれか。
    - landRatio: 土地権利割合（数値、パーセント）。不明なら 20。
    - propertyAddress: 物件の住所（文字列）

    出力は純粋なJSON、またはJSONコードブロックのみにしてください。
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        // Search使用時は JSON Schema/MimeType を使用しない（ルールに従う）
      }
    });

    const data = parseJsonFromText(response.text);
    if (!data) {
      throw new Error("物件データのパースに失敗しました。");
    }

    const sources = response.candidates?.[0]?.groundingMetadata?.groundingChunks?.map(chunk => ({
      title: chunk.web?.title || "参照元",
      uri: chunk.web?.uri || ""
    })) || [];

    return { data, sources };
  } catch (error) {
    console.error("Extraction Error:", error);
    throw new Error("物件情報の取得に失敗しました。URLが正しいか、またはAIがアクセス可能か確認してください。");
  }
};

export const getCommuteInfo = async (origin: string, destination: string) => {
  const prompt = `住所「${origin}」から「${destination}」まで、公共交通機関を利用して最短ルートで何分かかるか教えてください。具体的なルートと所要時間を含めて回答してください。`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
      config: {
        tools: [{ googleMaps: {} }],
      },
    });

    const text = response.text || "情報を取得できませんでした。";
    const mapsChunk = response.candidates?.[0]?.groundingMetadata?.groundingChunks?.find(chunk => chunk.maps?.uri);
    const mapsUrl = mapsChunk?.maps?.uri || `https://www.google.com/maps/dir/${encodeURIComponent(origin)}/${encodeURIComponent(destination)}`;

    return { text, mapsUrl };
  } catch (error) {
    console.error("Maps Error:", error);
    return { text: "ルート検索中にエラーが発生しました。住所が正しいか確認してください。", mapsUrl: "" };
  }
};

