export const extractPropertyFromUrl = async (url: string) => {
  const ai = getAiInstance();
  const prompt = `
    あなたは不動産データの抽出エキスパートです。Google検索ツールを使用して、以下のURL（SUUMOなどの不動産サイト）の「物件概要」セクションを詳細に確認し、指定のJSON形式でデータを抽出してください。

    URL: ${url}

    【抽出・判定ルール】
    1. 価格 (purchasePrice): 「販売価格」や「価格」項目から取得（円単位の数値）。
    2. 管理費 (maintenanceFee): 「管理費」項目から月額を取得（数値）。
    3. 修繕積立金 (repairFund): 「修繕積立金」項目から月額を取得（数値）。
    4. 所在地 (propertyAddress): 「所在地」や「住所」から取得。
    5. 物件種別 (buildingType): 
       - 築年数が新しく「ZEH」や「長期優良」の記載があれば 'new_certified'
       - 2024年以降完成の新築なら 'new_standard'
       - それ以外（中古）なら 'existing'
    6. 土地権利割合 (landRatio): 不明な場合は 20 を設定。

    出力は以下のキーを持つ純粋なJSONオブジェクトのみとしてください：
    {
      "purchasePrice": number,
      "maintenanceFee": number,
      "repairFund": number,
      "buildingType": "new_certified" | "new_standard" | "existing",
      "landRatio": number,
      "propertyAddress": "string"
    }
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview", // 複雑な抽出タスクのためProモデルを使用
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
      }
    });

    const text = response.text;
    const data = parseJsonFromText(text);

    if (!data || !data.purchasePrice) {
      console.error("Extracted text was:", text);
      throw new Error("URLから物件情報を読み取れませんでした。物件概要が公開されていないか、形式が特殊な可能性があります。");
    }

    const sources = response.candidates?.[0]?.groundingMetadata?.groundingChunks?.map(chunk => ({
      title: chunk.web?.title || "参照元",
      uri: chunk.web?.uri || url
    })) || [{ title: "物件ページ", uri: url }];

    return { data, sources };
  } catch (error: any) {
    console.error("Extraction Error:", error);
    throw new Error(error.message || "物件情報の取得に失敗しました。");
  }
};

export const getCommuteInfo = async (origin: string, destination: string) => {
  const ai = getAiInstance();
  const prompt = `住所「${origin}」から「${destination}」まで、公共交通機関を利用して最短ルートで何分かかるか教えてください。具体的なルートと所要時間を含めて回答してください。`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
      config: {
        tools: [{ googleMaps: {} }],
      },
    });

    const text = response.text || "情報を取得できませんでした。";
    const mapsChunk = response.candidates?.[0]?.groundingMetadata?.groundingChunks?.find(chunk => chunk.maps?.uri);
    const mapsUrl = mapsChunk?.maps?.uri || `https://www.google.com/maps/dir/${encodeURIComponent(origin)}/${encodeURIComponent(destination)}`;

    return { text, mapsUrl };
  } catch (error) {
    console.error("Maps Error:", error);
    return { text: "ルート検索中にエラーが発生しました。住所が正しいか確認してください。", mapsUrl: "" };
  }
};

