                     <div className="flex items-baseline justify-center gap-3">
                       <span className="text-xs font-bold text-emerald-200">月々</span>
                       <span className="text-5xl font-black text-white">{formatCurrency(Math.abs(monthlyAdvantage))}</span>
                       <span className="text-xl font-bold text-white">{monthlyAdvantage >= 0 ? 'お得' : '損'}</span>
                     </div>
                  </div>
               </div>
            </section>

            {/* 4. AI Insights & Location Analysis */}
            <div className="space-y-8">
              <div className="flex items-center gap-3 px-4">
                <BrainCircuit className="text-blue-600 w-6 h-6" />
                <h3 className="text-xl font-black text-slate-800 tracking-tight">AI & 立地多角分析</h3>
                <button onClick={runAiAnalysis} disabled={loadingAi} className="ml-auto bg-slate-900 text-white px-4 py-2 rounded-xl text-xs font-black flex items-center gap-2 hover:bg-slate-800 transition-all shadow-md disabled:opacity-50">
                  {loadingAi ? <RefreshCcw size={14} className="animate-spin" /> : <Zap size={14} className="fill-current" />} AI再診断
                </button>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="bg-white rounded-[2.5rem] p-8 border border-slate-200 shadow-sm space-y-6">
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-3">
                       <div className="bg-blue-100 p-2 rounded-xl"><Waves className="w-5 h-5 text-blue-600" /></div>
                       <h3 className="font-black text-slate-800">ハザードリスク評価</h3>
                    </div>
                    {loadingHazard && <Loader2 className="w-4 h-4 animate-spin text-blue-500" />}
                  </div>
                  <div className="text-sm leading-relaxed text-slate-600 bg-slate-50 p-6 rounded-2xl border border-slate-100 min-h-[150px]">
                    {hazardInfo ? (
                      <div className="space-y-4">
                        <p className="whitespace-pre-wrap">{hazardInfo.text}</p>
                        {hazardInfo.sources.length > 0 && (
                          <div className="pt-4 border-t border-slate-200">
                            <p className="text-[10px] font-black text-slate-400 mb-2 uppercase tracking-widest">参照ソース</p>
                            <div className="flex flex-wrap gap-2">
                              {hazardInfo.sources.map((s, i) => (
                                <a key={i} href={s.uri} target="_blank" rel="noopener noreferrer" className="flex items-center gap-1 text-[10px] bg-white px-2 py-1 rounded border border-slate-200 text-blue-600 hover:bg-blue-50 transition-colors">
                                  <ExternalLink size={10} /> {s.title}
                                </a>
                              ))}
                            </div>
                          </div>
                        )}
                      </div>
                    ) : <p className="text-slate-400 italic">住所を入力し「物件情報を解析」を押すと表示されます。</p>}
                  </div>
                </div>

                <div className="bg-white rounded-[2.5rem] p-8 border border-slate-200 shadow-sm space-y-6">
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-3">
                       <div className="bg-amber-100 p-2 rounded-xl"><History className="w-5 h-5 text-amber-600" /></div>
                       <h3 className="font-black text-slate-800">出口戦略の見立て</h3>
                    </div>
                    {loadingExit && <Loader2 className="w-4 h-4 animate-spin text-amber-500" />}
                  </div>
                  <div className="text-sm leading-relaxed text-slate-600 bg-slate-50 p-6 rounded-2xl border border-slate-100 min-h-[150px]">
                    {exitStrategy ? (
                      <div className="space-y-4">
                        <p className="whitespace-pre-wrap">{exitStrategy.text}</p>
                        {exitStrategy.sources.length > 0 && (
                          <div className="pt-4 border-t border-slate-200">
                            <p className="text-[10px] font-black text-slate-400 mb-2 uppercase tracking-widest">周辺の成約・売出事例</p>
                            <div className="flex flex-wrap gap-2">
                              {exitStrategy.sources.map((s, i) => (
                                <a key={i} href={s.uri} target="_blank" rel="noopener noreferrer" className="flex items-center gap-1 text-[10px] bg-white px-2 py-1 rounded border border-slate-200 text-amber-600 hover:bg-amber-50 transition-colors">
                                  <ExternalLink size={10} /> {s.title}
                                </a>
                              ))}
                            </div>
                          </div>
                        )}
                      </div>
                    ) : <p className="text-slate-400 italic">将来、同等の築年数になった際の相場予測を表示します。</p>}
                  </div>
                </div>
              </div>

              <div className="bg-white rounded-[2.5rem] p-10 border border-slate-200 shadow-sm">
                <div className="flex items-center gap-3 mb-6">
                  <div className="bg-indigo-100 p-2 rounded-xl"><BrainCircuit className="w-6 h-6 text-indigo-600" /></div>
                  <h3 className="text-xl font-black text-slate-800 tracking-tight">AI 総合ファイナンスアドバイス</h3>
                </div>
                <div className="text-sm leading-relaxed text-slate-700 min-h-[150px]">
                  {loadingAi ? <div className="flex justify-center py-10"><Loader2 className="animate-spin text-indigo-500" /></div> : aiAdvice || "AI再診断ボタンを押すと、家計負担やリスクを踏まえた個別の提案が表示されます。"}
                </div>
              </div>
            </div>

          </div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { SimulationInputs, SimulationResults, BuildingType } from './types';
import { INITIAL_VALUES } from './constants';
import { calculateSimulation, formatCurrency } from './utils/calculations';
import { getAIAnalysis, extractPropertyFromUrl, getHazardAnalysis, getExitStrategyData } from './services/geminiService';
import { 
  TrendingUp, 
  Wallet, 
  RefreshCcw, 
  BrainCircuit,
  Calculator,
  Zap,
  Link as LinkIcon,
  ExternalLink,
  Loader2,
  BadgeDollarSign,
  Clock,
  History,
  Search,
  CheckCircle2,
  XCircle,
  Scale,
  Percent,
  ReceiptJapaneseYen,
  BarChart3,
  Waves,
  ArrowDownCircle,
  ArrowUpCircle,
  HelpCircle,
  PiggyBank
} from 'lucide-react';

const App: React.FC = () => {
  const [inputs, setInputs] = useState<SimulationInputs>(INITIAL_VALUES);
  const [results, setResults] = useState<SimulationResults>(calculateSimulation(inputs));
  const [aiAdvice, setAiAdvice] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);

  // Analytical States
  const [hazardInfo, setHazardInfo] = useState<{ text: string, sources: {title: string, uri: string}[] } | null>(null);
  const [loadingHazard, setLoadingHazard] = useState(false);
  const [exitStrategy, setExitStrategy] = useState<{ text: string, sources: {title: string, uri: string}[] } | null>(null);
  const [loadingExit, setLoadingExit] = useState(false);

  // URL Import States
  const [propertyUrl, setPropertyUrl] = useState('');
  const [isExtracting, setIsExtracting] = useState(false);

  useEffect(() => {
    setResults(calculateSimulation(inputs));
  }, [inputs]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target;
    const checked = (e.target as HTMLInputElement).checked;

    setInputs(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : 
              (name === 'buildingType' ? value : (parseFloat(value) || 0))
    }));
  };

  const handleUrlExtract = async () => {
    if (!propertyUrl) return;
    setIsExtracting(true);
    try {
      const { data } = await extractPropertyFromUrl(propertyUrl);
      setInputs(prev => ({
        ...prev,
        purchasePrice: data.purchasePrice || prev.purchasePrice,
        maintenanceFee: data.maintenanceFee || prev.maintenanceFee,
        repairFund: data.repairFund || prev.repairFund,
        buildingType: (data.buildingType as BuildingType) || prev.buildingType,
        landRatio: data.landRatio || prev.landRatio,
        propertyAddress: data.propertyAddress || prev.propertyAddress,
      }));
      if (data.propertyAddress) {
        fetchLocationAnalysis(data.propertyAddress);
      }
    } catch (error: any) {
      alert(error.message);
    } finally {
      setIsExtracting(false);
    }
  };

  const fetchLocationAnalysis = async (address: string) => {
    setLoadingHazard(true);
    setLoadingExit(true);
    const [hazard, exit] = await Promise.all([
      getHazardAnalysis(address),
      getExitStrategyData(address, inputs.yearsHeld)
    ]);
    setHazardInfo(hazard);
    setExitStrategy(exit);
    setLoadingHazard(false);
    setLoadingExit(false);
  };

  const handleManualAddressAnalysis = () => {
    if (!inputs.propertyAddress) {
      alert("物件の住所を入力してください。");
      return;
    }
    fetchLocationAnalysis(inputs.propertyAddress);
  };

  const runAiAnalysis = async () => {
    setLoadingAi(true);
    const advice = await getAIAnalysis(inputs, results);
    setAiAdvice(advice.text);
    setLoadingAi(false);
  };

  // 売却時の純粋な手残り現金
  const realSellingCashIn = results.sellingPrice - results.remainingMortgageBalance - results.sellingCosts - results.taxAmount;
  // 純利益（手残り － 頭金）
  const pureProfitFromSale = realSellingCashIn - inputs.downPayment;

  // 実質月額コスト
  const totalMonths = inputs.yearsHeld * 12;
  const buyRealMonthlyCost = results.netProfit >= 0 ? 0 : Math.abs(results.netProfit) / totalMonths;
  const rentRealMonthlyCost = results.totalRentalCost / totalMonths;
  const monthlyAdvantage = rentRealMonthlyCost - buyRealMonthlyCost;

  // 譲渡所得の簡易計算表示用
  const estimatedCapitalGain = results.sellingPrice - (inputs.purchasePrice + results.initialTotalCost) - results.sellingCosts;

  return (
    <div className="min-h-screen bg-slate-50 pb-20 font-['Inter','Noto_Sans_JP']">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-50 shadow-sm">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="bg-slate-900 p-1.5 rounded-lg">
              <TrendingUp className="text-white w-6 h-6" />
            </div>
            <h1 className="text-xl font-bold text-slate-800 tracking-tight">Condo Wealth <span className="text-blue-600">Pro</span></h1>
          </div>
          <button onClick={() => {setInputs(INITIAL_VALUES); setHazardInfo(null); setExitStrategy(null);}} className="text-sm text-slate-500 hover:text-blue-600 flex items-center gap-1">
            <RefreshCcw className="w-4 h-4" /> リセット
          </button>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 mt-8">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
          {/* 左カラム: 入力設定 */}
          <aside className="lg:col-span-4 space-y-6">
            <section className="bg-slate-900 rounded-2xl shadow-lg p-6 text-white border border-slate-800">
              <div className="flex items-center gap-2 mb-4">
                <BrainCircuit className="w-5 h-5 text-blue-400" />
                <h2 className="text-lg font-bold">AI物件データ取得</h2>
              </div>
              <div className="space-y-3">
                <input 
                  type="text" placeholder="https://suumo.jp/..." value={propertyUrl} onChange={(e) => setPropertyUrl(e.target.value)}
                  className="w-full px-4 py-3 bg-white/10 border border-white/20 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
                />
                <button onClick={handleUrlExtract} disabled={isExtracting || !propertyUrl} className="w-full bg-blue-600 hover:bg-blue-500 disabled:bg-slate-700 text-white py-3 rounded-xl font-bold text-sm transition-all flex items-center justify-center gap-2">
                  {isExtracting ? <Loader2 className="w-4 h-4 animate-spin" /> : <Zap className="w-4 h-4 fill-current" />} 解析して自動入力
                </button>
              </div>
            </section>

            <section className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6">
              <div className="flex items-center gap-2 mb-6">
                <Calculator className="w-5 h-5 text-blue-600" /><h2 className="text-lg font-bold">シミュレーション条件</h2>
              </div>
              <div className="space-y-4">
                <div>
                  <label className="block text-sm font-semibold text-slate-700 mb-1">物件所在地</label>
                  <div className="flex gap-2">
                    <input type="text" name="propertyAddress" value={inputs.propertyAddress} onChange={(e) => setInputs({...inputs, propertyAddress: e.target.value})} className="flex-1 px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm" />
                    <button onClick={handleManualAddressAnalysis} className="p-2 bg-slate-100 hover:bg-slate-200 rounded-lg text-slate-600"><Search size={18} /></button>
                  </div>
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div className="col-span-2">
                    <label className="block text-sm font-semibold text-slate-700 mb-1">購入価格 (円)</label>
                    <input type="number" name="purchasePrice" value={inputs.purchasePrice} onChange={handleInputChange} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg font-black text-lg text-blue-600" />
                  </div>
                  <div className="col-span-2">
                    <label className="block text-sm font-semibold text-slate-700 mb-1">手取り月収 (円)</label>
                    <input type="number" name="monthlyTakeHomeIncome" value={inputs.monthlyTakeHomeIncome} onChange={handleInputChange} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg font-bold" />
                  </div>
                  <div><label className="block text-sm font-semibold text-slate-700 mb-1">頭金 (円)</label><input type="number" name="downPayment" value={inputs.downPayment} onChange={handleInputChange} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg font-bold text-emerald-600" /></div>
                  <div><label className="block text-sm font-semibold text-slate-700 mb-1">金利 (%)</label><input type="number" step="0.01" name="interestRate" value={inputs.interestRate} onChange={handleInputChange} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg" /></div>
                </div>
                <div className="grid grid-cols-2 gap-4 pt-4 border-t border-slate-100">
                  <div><label className="block text-sm font-semibold text-slate-700 mb-1">管理費 (月額)</label><input type="number" name="maintenanceFee" value={inputs.maintenanceFee} onChange={handleInputChange} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg" /></div>
