        ...prev,
        purchasePrice: data.purchasePrice || prev.purchasePrice,
        maintenanceFee: data.maintenanceFee || prev.maintenanceFee,
        repairFund: data.repairFund || prev.repairFund,
        propertyAddress: data.propertyAddress || prev.propertyAddress,
