        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="bg-slate-900 p-1.5 rounded-lg">
              <TrendingUp className="text-white w-6 h-6" />
            </div>
            <h1 className="text-xl font-bold text-slate-800 tracking-tight">Condo Wealth <span className="text-blue-600">Pro</span></h1>
          </div>
          <button onClick={() => {setInputs(INITIAL_VALUES); setHazardInfo(null); setExitStrategy(null);}} className="text-sm text-slate-500 hover:text-blue-600 flex items-center gap-1">
            <RefreshCcw className="w-4 h-4" /> リセット
          </button>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 mt-8">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
          {/* 設定エリア（サイドバー） */}
          <aside className="lg:col-span-4 space-y-6">
            <section className="bg-slate-900 rounded-2xl shadow-lg p-6 text-white border border-slate-800">
