                  <div><label className="block text-xs font-black text-slate-400 uppercase mb-1">保有期間 (年)</label><input type="number" name="yearsHeld" value={inputs.yearsHeld} onChange={handleInputChange} className="w-full px-4 py-2 bg-amber-50 border border-amber-200 rounded-lg font-black text-amber-700" /></div>

