};

export default App;

import React, { useState, useEffect } from 'react';
import { SimulationInputs, SimulationResults, BuildingType } from './types';
import { INITIAL_VALUES } from './constants';
import { calculateSimulation, formatCurrency } from './utils/calculations';
import { getAIAnalysis, extractPropertyFromUrl, getHazardAnalysis, getExitStrategyData } from './services/geminiService';
import { 
  TrendingUp, 
  Wallet, 
  RefreshCcw, 
  BrainCircuit,
  Calculator,
  Zap,
  Loader2,
  BadgeDollarSign,
  CheckCircle2,
  XCircle,
  Scale,
  ReceiptJapaneseYen,
  BarChart3,
  Waves,
  History,
  PiggyBank,
  PlusCircle,
  MinusCircle,
  Info,
  Building2,
  Clock,
  MapPin,
  Percent,
  ArrowRightLeft,
  Coins
} from 'lucide-react';

const App: React.FC = () => {
  const [inputs, setInputs] = useState<SimulationInputs>(INITIAL_VALUES);
  const [results, setResults] = useState<SimulationResults>(calculateSimulation(inputs));
  const [aiAdvice, setAiAdvice] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);

  const [hazardInfo, setHazardInfo] = useState<{ text: string, sources: {title: string, uri: string}[] } | null>(null);
  const [loadingHazard, setLoadingHazard] = useState(false);
  const [exitStrategy, setExitStrategy] = useState<{ text: string, sources: {title: string, uri: string}[] } | null>(null);
  const [loadingExit, setLoadingExit] = useState(false);

  const [propertyUrl, setPropertyUrl] = useState('');
  const [isExtracting, setIsExtracting] = useState(false);

  useEffect(() => {
    setResults(calculateSimulation(inputs));
  }, [inputs]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target;
    const checked = (e.target as HTMLInputElement).checked;
    setInputs(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : 
              (name === 'buildingType' ? value : (parseFloat(value) || 0))
    }));
  };

  const handleUrlExtract = async () => {
    if (!propertyUrl) return;
    setIsExtracting(true);
    try {
      const { data } = await extractPropertyFromUrl(propertyUrl);
      setInputs(prev => ({
        ...prev,
        purchasePrice: data.purchasePrice || prev.purchasePrice,
        maintenanceFee: data.maintenanceFee || prev.maintenanceFee,
        repairFund: data.repairFund || prev.repairFund,
        propertyAddress: data.propertyAddress || prev.propertyAddress,
        buildingType: (data.buildingType as BuildingType) || prev.buildingType,
      }));
      if (data.propertyAddress) {
        fetchLocationAnalysis(data.propertyAddress);
      }
    } catch (error: any) {
      alert(error.message);
    } finally {
      setIsExtracting(false);
    }
  };

  const fetchLocationAnalysis = async (address: string) => {
    setLoadingHazard(true);
    setLoadingExit(true);
    const [hazard, exit] = await Promise.all([
      getHazardAnalysis(address),
      getExitStrategyData(address, inputs.yearsHeld)
    ]);
    setHazardInfo(hazard);
    setExitStrategy(exit);
    setLoadingHazard(false);
    setLoadingExit(false);
  };

  const runAiAnalysis = async () => {
    setLoadingAi(true);
    const advice = await getAIAnalysis(inputs, results);
    setAiAdvice(advice.text);
    setLoadingAi(false);
  };

  // ①コスト（支出合計）
  const bucket1_costs = 
    inputs.downPayment + 
    results.initialBrokerageFee + 
    results.initialOtherCosts + 
    results.totalMortgagePayments +   // ローン返済累計
    results.totalMaintenanceCosts +   // 管理費累計
    results.totalTaxPaid +            // 固定資産税累計
    results.remainingMortgageBalance + 
    results.sellingCosts + 
    results.taxAmount;

  // ②利益（収入合計）
  const bucket2_gains = 
    results.sellingPrice + 
    results.totalMortgageTaxCredit;

  // 純利益 (②利益 － ①コスト)
  const netInvestmentResult = bucket2_gains - bucket1_costs;

  // 実質住居コスト/月
  const realMonthlyCost = netInvestmentResult >= 0 ? 0 : Math.abs(netInvestmentResult / (inputs.yearsHeld * 12));

  // 賃貸コストの内訳計算
  const rentalBase = results.estimatedMonthlyRent;
  const rentalManagement = rentalBase * 0.05;
  const rentalRenewalMonthly = (rentalBase / 24);
  const totalMonthlyRental = rentalBase + rentalManagement + rentalRenewalMonthly;

  return (
    <div className="min-h-screen bg-slate-50 pb-20 font-['Inter','Noto_Sans_JP']">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-50 shadow-sm">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="bg-slate-900 p-1.5 rounded-lg">
              <TrendingUp className="text-white w-6 h-6" />
            </div>
            <h1 className="text-xl font-bold text-slate-800 tracking-tight">Condo Wealth <span className="text-blue-600">Pro</span></h1>
          </div>
          <button onClick={() => {setInputs(INITIAL_VALUES); setHazardInfo(null); setExitStrategy(null);}} className="text-sm text-slate-500 hover:text-blue-600 flex items-center gap-1">
            <RefreshCcw className="w-4 h-4" /> リセット
          </button>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 mt-8">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
          {/* 設定エリア（サイドバー） */}
          <aside className="lg:col-span-4 space-y-6">
            <section className="bg-slate-900 rounded-2xl shadow-lg p-6 text-white border border-slate-800">
              <div className="flex items-center gap-2 mb-4">
                <BrainCircuit className="w-5 h-5 text-blue-400" />
                <h2 className="text-lg font-bold">AI物件データ解析</h2>
              </div>
              <div className="space-y-3">
                <input 
                  type="text" placeholder="物件URL（SUUMO等）を貼り付け" value={propertyUrl} onChange={(e) => setPropertyUrl(e.target.value)}
                  className="w-full px-4 py-3 bg-white/10 border border-white/20 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
                />
                <button onClick={handleUrlExtract} disabled={isExtracting || !propertyUrl} className="w-full bg-blue-600 hover:bg-blue-500 disabled:bg-slate-700 text-white py-3 rounded-xl font-bold text-sm transition-all flex items-center justify-center gap-2">
                  {isExtracting ? <Loader2 className="w-4 h-4 animate-spin" /> : <Zap className="w-4 h-4 fill-current" />} 解析・反映
                </button>
              </div>
            </section>

            <section className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6">
              <div className="flex items-center gap-2 mb-6">
                <Calculator className="w-5 h-5 text-blue-600" /><h2 className="text-lg font-bold">購入・ローン詳細条件</h2>
              </div>
              <div className="space-y-4">
                <div>
                  <label className="block text-xs font-black text-slate-400 uppercase mb-1">物件種別</label>
                  <select name="buildingType" value={inputs.buildingType} onChange={handleInputChange} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm font-bold focus:ring-2 focus:ring-blue-500 outline-none">
                    <option value="new_standard">新築（一般）</option>
                    <option value="new_certified">新築（長期優良住宅等）</option>
                    <option value="existing">中古マンション（仲介）</option>
                  </select>
                </div>

                <div>
                  <label className="block text-xs font-black text-slate-400 uppercase mb-1 flex items-center gap-1"><MapPin size={12} /> 所在地（住所）</label>
                  <input type="text" name="propertyAddress" value={inputs.propertyAddress} onChange={(e) => setInputs({...inputs, propertyAddress: e.target.value})} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-xs" placeholder="東京都港区..." />
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div className="col-span-2">
                    <label className="block text-xs font-black text-slate-400 uppercase mb-1">購入価格 (円)</label>
                    <input type="number" name="purchasePrice" value={inputs.purchasePrice} onChange={handleInputChange} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg font-black text-lg text-blue-600" />
                  </div>
                  <div className="col-span-2">
                    <label className="block text-xs font-black text-slate-400 uppercase mb-1">手取り月収 (円)</label>
                    <input type="number" name="monthlyTakeHomeIncome" value={inputs.monthlyTakeHomeIncome} onChange={handleInputChange} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg font-bold" />
                  </div>
                  <div><label className="block text-xs font-black text-slate-400 uppercase mb-1">頭金 (円)</label><input type="number" name="downPayment" value={inputs.downPayment} onChange={handleInputChange} className="w-full px-4 py-2 bg-emerald-50 border border-emerald-200 rounded-lg font-bold text-emerald-700" /></div>
                  <div><label className="block text-xs font-black text-slate-400 uppercase mb-1 flex items-center gap-1"><Clock size={12} /> ローン期間(年)</label><input type="number" name="mortgageTerm" value={inputs.mortgageTerm} onChange={handleInputChange} className="w-full px-4 py-2 bg-blue-50 border border-blue-200 rounded-lg font-black text-blue-700" /></div>
                  <div><label className="block text-xs font-black text-slate-400 uppercase mb-1">金利 (%)</label><input type="number" step="0.01" name="interestRate" value={inputs.interestRate} onChange={handleInputChange} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg font-bold" /></div>
                  <div><label className="block text-xs font-black text-slate-400 uppercase mb-1">保有期間 (年)</label><input type="number" name="yearsHeld" value={inputs.yearsHeld} onChange={handleInputChange} className="w-full px-4 py-2 bg-amber-50 border border-amber-200 rounded-lg font-black text-amber-700" /></div>

                  <div className="col-span-2">
                    <label className="block text-xs font-black text-slate-400 uppercase mb-1 flex items-center gap-1"><Percent size={12} /> 予想価格変化率 (年利%)</label>
                    <input type="number" step="0.1" name="appreciationRate" value={inputs.appreciationRate} onChange={handleInputChange} className="w-full px-4 py-2 bg-rose-50 border border-rose-200 rounded-lg font-black text-rose-700" />
                  </div>
                </div>

                <div className="pt-4 border-t border-slate-100 grid grid-cols-2 gap-4">
                  <div className="col-span-2">
                    <label className="block text-xs font-black text-slate-400 uppercase mb-1 flex items-center gap-1"><ArrowRightLeft size={12} /> 比較対象の賃貸家賃</label>
                    <input type="number" name="estimatedMonthlyRent" value={inputs.estimatedMonthlyRent} onChange={handleInputChange} className="w-full px-4 py-2 bg-slate-900 text-white border border-slate-700 rounded-lg font-bold" />
                  </div>
                  <div><label className="block text-xs font-black text-slate-400 uppercase mb-1">購入物件 管理費/月</label><input type="number" name="maintenanceFee" value={inputs.maintenanceFee} onChange={handleInputChange} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-xs" /></div>
                  <div><label className="block text-xs font-black text-slate-400 uppercase mb-1">購入物件 積立金/月</label><input type="number" name="repairFund" value={inputs.repairFund} onChange={handleInputChange} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-xs" /></div>
                </div>
              </div>
            </section>
          </aside>

          {/* メイン解析結果エリア */}
          <div className="lg:col-span-8 space-y-10">

            {/* 毎月の収支セクション */}
