              <div className="bg-slate-50 px-8 py-5 border-b border-slate-100 flex items-center gap-3">
                <ReceiptJapaneseYen className="text-blue-600 w-6 h-6" />
                <h3 className="text-lg font-black text-slate-800">所有期間中の毎月のキャッシュフロー</h3>
              </div>
              <div className="p-8 grid grid-cols-1 md:grid-cols-2 gap-10">
                <div className="space-y-4">
                  <div className="space-y-2">
                    <div className="flex justify-between text-sm border-b pb-2"><span className="text-slate-500">ローン返済</span><span className="font-bold">{formatCurrency(results.monthlyMortgagePayment)}</span></div>
                    <div className="flex justify-between text-sm border-b pb-2"><span className="text-slate-500">管理費・修繕積立金</span><span className="font-bold">{formatCurrency(results.monthlyMaintenanceFee + results.monthlyRepairFund)}</span></div>
                    <div className="flex justify-between text-sm border-b pb-2"><span className="text-slate-500">固定資産税等(月換算)</span><span className="font-bold">{formatCurrency(results.monthlyTaxEquivalent)}</span></div>
