                <div className="text-sm text-slate-600 bg-slate-50 p-6 rounded-2xl border border-slate-100 min-h-[120px]">
                  {loadingHazard ? <Loader2 className="animate-spin mx-auto text-blue-500" /> : hazardInfo ? hazardInfo.text : "AIがリスクを判定します。"}
