                    <label className="block text-xs font-black text-slate-400 uppercase mb-1">購入価格 (円)</label>
                    <input type="number" name="purchasePrice" value={inputs.purchasePrice} onChange={handleInputChange} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg font-black text-lg text-blue-600 print:bg-transparent print:border-none print:px-0" />
