                  <select name="buildingType" value={inputs.buildingType} onChange={handleInputChange} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg font-bold focus:ring-2 focus:ring-blue-500 outline-none print:bg-transparent print:border-none print:px-0">
                    <option value="new_standard">新築（一般）</option>
