                      <div className="pt-3 border-t-2 border-rose-200 flex justify-between items-center">
                        <span className="text-rose-800 font-black">① すべての支出合計</span>
                        <span className="text-xl font-black text-rose-800">{formatCurrency(bucket1_costs)}</span>
                      </div>
                    </div>
                  </div>
                  <div className="space-y-6 flex flex-col">
                    <div className="flex items-center gap-2 text-emerald-600 font-black text-xs uppercase border-b border-emerald-100 pb-2">
                      <PlusCircle size={16} /> ② 利益（回収合計）
                    </div>
                    <div className="space-y-3 text-sm flex-1">
                      <div className="flex justify-between items-center p-4 bg-emerald-50 rounded-2xl border border-emerald-100"><span className="text-emerald-700 font-black text-lg">想定売却価格</span><span className="font-black text-2xl text-emerald-700">{formatCurrency(results.sellingPrice)}</span></div>
                      <div className="flex justify-between items-center px-2"><span className="text-slate-500 font-bold">ローン控除による還付累計</span><span className="font-bold text-emerald-600">+{formatCurrency(results.totalMortgageTaxCredit)}</span></div>
                      <div className="pt-3 border-t-2 border-emerald-200 flex justify-between items-center mt-auto">
                        <span className="text-emerald-800 font-black">② すべての収入合計</span>
                        <span className="text-xl font-black text-emerald-800">{formatCurrency(bucket2_gains)}</span>
                      </div>
                    </div>
                  </div>
                </div>

                {/* Net Wealth Creation */}
                <div className="bg-slate-900 rounded-[2.5rem] p-10 text-white shadow-2xl relative overflow-hidden flex flex-col items-center text-center">
                  <div className="absolute top-0 right-0 p-8 opacity-5"><Scale size={120} /></div>
                  <div className="space-y-2 mb-10">
                    <p className="text-[10px] font-black uppercase tracking-[0.3em] text-blue-400">Net Wealth Creation</p>
                    <h4 className="text-2xl font-black">資産形成の最終結果</h4>
                    <span className={`text-6xl font-black tracking-tighter mt-4 block ${netInvestmentResult >= 0 ? 'text-emerald-400' : 'text-rose-400'}`}>
                      {formatCurrency(netInvestmentResult)}
                    </span>
                  </div>

                  <div className="w-full grid grid-cols-1 md:grid-cols-2 gap-10 border-t border-white/10 pt-10">
                    <div className="space-y-4 text-center">
                      <div className="flex items-center justify-center gap-2 text-blue-400"><Building2 size={16} /><span className="text-xs font-black uppercase tracking-widest">購入時の実質住居コスト</span></div>
                      <div className="bg-white/5 rounded-2xl p-6 border border-white/5"><div className="text-4xl font-black text-white">{formatCurrency(realMonthlyCost)}<span className="text-sm ml-1 text-slate-400">/月</span></div></div>
                    </div>
                    <div className="space-y-4 text-center">
                      <div className="flex items-center justify-center gap-2 text-slate-400"><ArrowRightLeft size={16} /><span className="text-xs font-black uppercase tracking-widest">賃貸コスト(月換算)</span></div>
                      <div className="bg-white/5 rounded-2xl p-6 border border-white/5"><div className="text-2xl font-black text-slate-300">{formatCurrency(totalMonthlyRental)}<span className="text-xs ml-1 font-normal">/月</span></div></div>
                    </div>
                  </div>
                </div>
              </div>
            </section>

            {/* AI 解析 & 立地診断 */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="bg-white rounded-[2rem] p-8 border border-slate-200 shadow-sm space-y-4">
                <div className="flex items-center gap-3"><Waves className="w-5 h-5 text-blue-600" /><h3 className="font-black text-slate-800">立地ハザード評価</h3></div>
                <div className="text-sm text-slate-600 bg-slate-50 p-6 rounded-2xl border border-slate-100 min-h-[120px]">
                  {loadingHazard ? <Loader2 className="animate-spin mx-auto text-blue-500" /> : hazardInfo ? hazardInfo.text : "解析結果がここに表示されます。"}
                </div>
              </div>
              <div className="bg-white rounded-[2rem] p-8 border border-slate-200 shadow-sm space-y-4">
                <div className="flex items-center gap-3"><History className="w-5 h-5 text-amber-600" /><h3 className="font-black text-slate-800">出口戦略・将来相場</h3></div>
                <div className="text-sm text-slate-600 bg-slate-50 p-6 rounded-2xl border border-slate-100 min-h-[120px]">
                  {loadingExit ? <Loader2 className="animate-spin mx-auto text-amber-500" /> : exitStrategy ? exitStrategy.text : "将来の見込みを予測します。"}
                </div>
              </div>
            </div>

            <section className="bg-white rounded-[2rem] p-10 border border-slate-200 shadow-sm">
              <div className="flex items-center justify-between mb-8">
                <div className="flex items-center gap-3"><BrainCircuit className="w-6 h-6 text-indigo-600" /><h3 className="text-xl font-black text-slate-800">AI 財務診断</h3></div>
                <button type="button" onClick={runAiAnalysis} disabled={loadingAi} className="no-print bg-slate-900 text-white px-6 py-2.5 rounded-xl text-xs font-black flex items-center gap-2 hover:bg-slate-800 active:scale-95 transition-all">
                  {loadingAi ? <Loader2 size={14} className="animate-spin" /> : <Zap size={14} className="fill-current" />} 再診断
                </button>
              </div>
              <div className="text-sm leading-relaxed text-slate-700 min-h-[150px] whitespace-pre-wrap bg-slate-50 p-8 rounded-[1.5rem] italic shadow-inner border border-slate-100">
                {aiAdvice || "AIアドバイスがここに表示されます。"}
              </div>
            </section>
          </div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { SimulationInputs, SimulationResults, BuildingType } from './types';
import { INITIAL_VALUES } from './constants';
import { calculateSimulation, formatCurrency } from './utils/calculations';
import { getAIAnalysis, extractPropertyFromUrl, getHazardAnalysis, getExitStrategyData } from './services/geminiService';
import { 
  TrendingUp, 
  Wallet, 
  RefreshCcw, 
  BrainCircuit,
  Calculator,
  Zap,
  Loader2,
  BadgeDollarSign,
  CheckCircle2,
  XCircle,
  Scale,
  ReceiptJapaneseYen,
  BarChart3,
  Waves,
  History,
  PiggyBank,
  PlusCircle,
  MinusCircle,
  Info,
  Building2,
  Clock,
  MapPin,
  Percent,
  ArrowRightLeft,
  Coins,
  Printer,
  FileSpreadsheet,
  ExternalLink
} from 'lucide-react';

const App: React.FC = () => {
  const [inputs, setInputs] = useState<SimulationInputs>(INITIAL_VALUES);
  const [results, setResults] = useState<SimulationResults>(calculateSimulation(inputs));
  const [aiAdvice, setAiAdvice] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);

  const [hazardInfo, setHazardInfo] = useState<{ text: string, sources: {title: string, uri: string}[] } | null>(null);
  const [loadingHazard, setLoadingHazard] = useState(false);
  const [exitStrategy, setExitStrategy] = useState<{ text: string, sources: {title: string, uri: string}[] } | null>(null);
  const [loadingExit, setLoadingExit] = useState(false);

  const [propertyUrl, setPropertyUrl] = useState('');
  const [isExtracting, setIsExtracting] = useState(false);

  useEffect(() => {
    setResults(calculateSimulation(inputs));
  }, [inputs]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target;
    const checked = (e.target as HTMLInputElement).checked;
    setInputs(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : 
              (name === 'buildingType' ? value : (parseFloat(value) || 0))
    }));
  };

  const handleUrlExtract = async () => {
    if (!propertyUrl) return;
    setIsExtracting(true);
    try {
      const { data } = await extractPropertyFromUrl(propertyUrl);
      setInputs(prev => ({
        ...prev,
        purchasePrice: data.purchasePrice || prev.purchasePrice,
        maintenanceFee: data.maintenanceFee || prev.maintenanceFee,
        repairFund: data.repairFund || prev.repairFund,
        propertyAddress: data.propertyAddress || prev.propertyAddress,
        buildingType: (data.buildingType as BuildingType) || prev.buildingType,
      }));
      if (data.propertyAddress) {
        fetchLocationAnalysis(data.propertyAddress);
      }
    } catch (error: any) {
      alert(error.message);
    } finally {
      setIsExtracting(false);
    }
  };

  const fetchLocationAnalysis = async (address: string) => {
    setLoadingHazard(true);
    setLoadingExit(true);
    const [hazard, exit] = await Promise.all([
      getHazardAnalysis(address),
      getExitStrategyData(address, inputs.yearsHeld)
    ]);
    setHazardInfo(hazard);
    setExitStrategy(exit);
    setLoadingHazard(false);
    setLoadingExit(false);
  };

  const runAiAnalysis = async () => {
    setLoadingAi(true);
    const advice = await getAIAnalysis(inputs, results);
    setAiAdvice(advice.text);
    setLoadingAi(false);
  };

  // CSV出力機能
  const handleExportCSV = () => {
    const rows = [
      ['項目', '値'],
      ['物件価格', inputs.purchasePrice],
      ['頭金', inputs.downPayment],
      ['ローン金利', inputs.interestRate + '%'],
      ['ローン期間', inputs.mortgageTerm + '年'],
      ['保有期間', inputs.yearsHeld + '年'],
      ['予想価格変化率', inputs.appreciationRate + '%/年'],
      [],
      ['シミュレーション結果', ''],
      ['想定売却価格', results.sellingPrice],
      ['最終純利益', results.netProfit],
      ['実質住居コスト/月', results.monthlyHousingCost],
      ['比較対象賃料/月', results.estimatedMonthlyRent],
      [],
      ['年次推移データ', ''],
      ['経過年数', '資産価値', 'ローン残債', '累計支出', '含み益(純資産)', '賃貸累計コスト']
    ];

    results.yearlyData.forEach(data => {
      rows.push([
        data.year + '年',
        Math.round(data.propertyValue),
        Math.round(data.mortgageBalance),
        Math.round(data.cumulativeCost),
        Math.round(data.equity),
        Math.round(data.cumulativeRentalCost)
      ]);
    });

    const csvContent = "\uFEFF" + rows.map(e => e.join(",")).join("\n");
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `condo_simulation_${new Date().toISOString().slice(0,10)}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handlePrint = () => {
    window.print();
  };

  // ①コスト（支出合計）
  const bucket1_costs = 
    inputs.downPayment + 
    results.initialBrokerageFee + 
    results.initialOtherCosts + 
    results.totalMortgagePayments +   
    results.totalMaintenanceCosts +   
    results.totalTaxPaid +            
    results.remainingMortgageBalance + 
    results.sellingCosts + 
    results.taxAmount;

  // ②利益（収入合計）
  const bucket2_gains = 
    results.sellingPrice + 
    results.totalMortgageTaxCredit;

  // 純利益
  const netInvestmentResult = bucket2_gains - bucket1_costs;
  const realMonthlyCost = netInvestmentResult >= 0 ? 0 : Math.abs(netInvestmentResult / (inputs.yearsHeld * 12));

  // 賃貸コスト
  const rentalBase = results.estimatedMonthlyRent;
  const rentalManagement = rentalBase * 0.05;
  const rentalRenewalMonthly = (rentalBase / 24);
  const totalMonthlyRental = rentalBase + rentalManagement + rentalRenewalMonthly;

  const googleMapsUrl = inputs.propertyAddress 
    ? `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(inputs.propertyAddress)}`
    : null;

  return (
    <div className="min-h-screen bg-slate-50 pb-20 font-['Inter','Noto_Sans_JP']">
      <style>{`
        @media print {
          .no-print { display: none !important; }
          body { background: white !important; padding: 0 !important; }
          main { margin-top: 0 !important; padding: 0 !important; }
          .max-w-7xl { max-width: 100% !important; width: 100% !important; margin: 0 !important; }
          .shadow-sm, .shadow-lg, .shadow-2xl { box-shadow: none !important; border: 1px solid #e2e8f0 !important; }
          header { position: static !important; border-bottom: 2px solid #e2e8f0 !important; }
          aside { border: none !important; }
          * { -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important; }
        }
      `}</style>

      <header className="bg-white border-b border-slate-200 sticky top-0 z-50 shadow-sm">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="bg-slate-900 p-1.5 rounded-lg">
              <TrendingUp className="text-white w-6 h-6" />
            </div>
            <h1 className="text-xl font-bold text-slate-800 tracking-tight">Condo Wealth <span className="text-blue-600">Pro</span></h1>
          </div>
          <div className="flex items-center gap-3">
            <button 
              type="button"
              onClick={handleExportCSV}
              className="no-print text-sm bg-emerald-600 text-white px-4 py-2 rounded-xl font-bold flex items-center gap-2 hover:bg-emerald-700 active:scale-95 transition-all shadow-md shadow-emerald-500/20 cursor-pointer"
            >
              <FileSpreadsheet className="w-4 h-4" /> CSV出力
            </button>
            <button 
              type="button"
              onClick={handlePrint}
              className="no-print text-sm bg-blue-600 text-white px-4 py-2 rounded-xl font-bold flex items-center gap-2 hover:bg-blue-700 active:scale-95 transition-all shadow-md shadow-blue-500/20 cursor-pointer"
            >
              <Printer className="w-4 h-4" /> PDF出力
            </button>
            <button 
              type="button"
              onClick={() => {setInputs(INITIAL_VALUES); setHazardInfo(null); setExitStrategy(null);}} 
              className="no-print text-sm text-slate-400 hover:text-rose-600 flex items-center gap-1 active:scale-95 transition-all"
            >
              <RefreshCcw className="w-4 h-4" />
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 mt-8">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
          {/* 設定エリア（サイドバー） */}
          <aside className="lg:col-span-4 space-y-6">
            <section className="no-print bg-slate-900 rounded-2xl shadow-lg p-6 text-white border border-slate-800">
              <div className="flex items-center gap-2 mb-4">
                <BrainCircuit className="w-5 h-5 text-blue-400" />
                <h2 className="text-lg font-bold">AI物件データ解析</h2>
              </div>
              <div className="space-y-3">
                <input 
                  type="text" placeholder="物件URL（SUUMO等）を貼り付け" value={propertyUrl} onChange={(e) => setPropertyUrl(e.target.value)}
                  className="w-full px-4 py-3 bg-white/10 border border-white/20 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
                />
                <button onClick={handleUrlExtract} disabled={isExtracting || !propertyUrl} className="w-full bg-blue-600 hover:bg-blue-500 disabled:bg-slate-700 text-white py-3 rounded-xl font-bold text-sm transition-all flex items-center justify-center gap-2">
                  {isExtracting ? <Loader2 className="w-4 h-4 animate-spin" /> : <Zap className="w-4 h-4 fill-current" />} 解析・反映
                </button>
              </div>
            </section>

            <section className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6">
              <div className="flex items-center gap-2 mb-6">
                <Calculator className="w-5 h-5 text-blue-600" /><h2 className="text-lg font-bold">購入・ローン詳細条件</h2>
              </div>
              <div className="space-y-4 text-sm">
                <div className="print:border-b print:pb-2">
                  <label className="block text-xs font-black text-slate-400 uppercase mb-1">物件種別</label>
                  <select name="buildingType" value={inputs.buildingType} onChange={handleInputChange} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg font-bold focus:ring-2 focus:ring-blue-500 outline-none print:bg-transparent print:border-none print:px-0">
                    <option value="new_standard">新築（一般）</option>
                    <option value="new_certified">新築（長期優良住宅等）</option>
                    <option value="existing">中古マンション（仲介）</option>
                  </select>
                </div>

                <div className="print:border-b print:pb-2">
                  <div className="flex items-center justify-between mb-1">
                    <label className="block text-xs font-black text-slate-400 uppercase flex items-center gap-1">
                      <MapPin size={12} /> 所在地（住所）
                    </label>
                    {googleMapsUrl && (
                      <a 
                        href={googleMapsUrl} 
                        target="_blank" 
                        rel="noopener noreferrer" 
                        className="no-print text-[10px] text-blue-500 hover:text-blue-700 flex items-center gap-0.5 font-bold transition-colors"
                      >
                        Mapで確認 <ExternalLink size={10} />
                      </a>
                    )}
                  </div>
                  <input type="text" name="propertyAddress" value={inputs.propertyAddress} onChange={(e) => setInputs({...inputs, propertyAddress: e.target.value})} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-xs print:bg-transparent print:border-none print:px-0" placeholder="東京都港区..." />
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div className="col-span-2 print:border-b print:pb-2">
                    <label className="block text-xs font-black text-slate-400 uppercase mb-1">購入価格 (円)</label>
                    <input type="number" name="purchasePrice" value={inputs.purchasePrice} onChange={handleInputChange} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg font-black text-lg text-blue-600 print:bg-transparent print:border-none print:px-0" />
                  </div>
                  <div className="col-span-2 print:border-b print:pb-2">
                    <label className="block text-xs font-black text-slate-400 uppercase mb-1">手取り月収 (円)</label>
                    <input type="number" name="monthlyTakeHomeIncome" value={inputs.monthlyTakeHomeIncome} onChange={handleInputChange} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg font-bold print:bg-transparent print:border-none print:px-0" />
                  </div>
                  <div className="print:border-b print:pb-2"><label className="block text-xs font-black text-slate-400 uppercase mb-1">頭金 (円)</label><input type="number" name="downPayment" value={inputs.downPayment} onChange={handleInputChange} className="w-full px-4 py-2 bg-emerald-50 border border-emerald-200 rounded-lg font-bold text-emerald-700 print:bg-transparent print:border-none print:px-0" /></div>
                  <div className="print:border-b print:pb-2"><label className="block text-xs font-black text-slate-400 uppercase mb-1 flex items-center gap-1"><Clock size={12} /> 期間(年)</label><input type="number" name="mortgageTerm" value={inputs.mortgageTerm} onChange={handleInputChange} className="w-full px-4 py-2 bg-blue-50 border border-blue-200 rounded-lg font-black text-blue-700 print:bg-transparent print:border-none print:px-0" /></div>
                  <div className="print:border-b print:pb-2"><label className="block text-xs font-black text-slate-400 uppercase mb-1">金利 (%)</label><input type="number" step="0.01" name="interestRate" value={inputs.interestRate} onChange={handleInputChange} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg font-bold print:bg-transparent print:border-none print:px-0" /></div>
                  <div className="print:border-b print:pb-2"><label className="block text-xs font-black text-slate-400 uppercase mb-1">保有(年)</label><input type="number" name="yearsHeld" value={inputs.yearsHeld} onChange={handleInputChange} className="w-full px-4 py-2 bg-amber-50 border border-amber-200 rounded-lg font-black text-amber-700 print:bg-transparent print:border-none print:px-0" /></div>
                </div>

                <div className="pt-4 border-t border-slate-100 space-y-4">
                  <div className="print:border-b print:pb-2">
                    <label className="block text-xs font-black text-slate-400 uppercase mb-1 flex items-center gap-1"><ArrowRightLeft size={12} /> 比較対象の賃貸家賃</label>
                    <input type="number" name="estimatedMonthlyRent" value={inputs.estimatedMonthlyRent} onChange={handleInputChange} className="w-full px-4 py-2 bg-slate-900 text-white border border-slate-700 rounded-lg font-bold print:bg-transparent print:border-none print:px-0 print:text-slate-800" />
                  </div>
                </div>
              </div>
            </section>
          </aside>

          {/* メイン解析結果エリア */}
          <div className="lg:col-span-8 space-y-10">

            {/* 毎月の収支 */}
