              <div className="bg-slate-50 px-8 py-5 border-b border-slate-100 flex items-center gap-3">
                <ReceiptJapaneseYen className="text-blue-600 w-6 h-6" />
                <h3 className="text-lg font-black text-slate-800">所有期間中の毎月のキャッシュフロー</h3>
              </div>
              <div className="p-8 grid grid-cols-1 md:grid-cols-2 gap-10">
                <div className="space-y-4">
                  <div className="space-y-2">
                    <div className="flex justify-between text-sm border-b pb-2"><span className="text-slate-500">住宅ローン返済</span><span className="font-bold">{formatCurrency(results.monthlyMortgagePayment)}</span></div>
                    <div className="flex justify-between text-sm border-b pb-2"><span className="text-slate-500">管理費・修繕積立金</span><span className="font-bold">{formatCurrency(results.monthlyMaintenanceFee + results.monthlyRepairFund)}</span></div>
                    <div className="flex justify-between text-sm border-b pb-2"><span className="text-slate-500">固定資産税・都市計画税(月割)</span><span className="font-bold">{formatCurrency(results.monthlyTaxEquivalent)}</span></div>
                  </div>
                  <div className="pt-4 space-y-4">
                    <div className="flex justify-between items-center">
                      <span className="text-xs font-black text-slate-400 uppercase">月間住居費 合計</span>
                      <span className="text-3xl font-black text-blue-600">{formatCurrency(results.monthlyHousingCost)}</span>
                    </div>
                    <div className="p-4 bg-emerald-50 rounded-2xl border border-emerald-100 flex justify-between items-center">
                      <div className="flex items-center gap-2">
                        <Coins className="text-emerald-600 w-4 h-4" />
                        <span className="text-xs font-black text-emerald-800 uppercase">手元に残る金額 (可処分所得)</span>
                      </div>
                      <span className="text-2xl font-black text-emerald-600">{formatCurrency(results.monthlySurplus)}</span>
                    </div>
                  </div>
                </div>
                <div className="bg-slate-900 rounded-3xl p-8 text-white flex flex-col justify-center">
                  <p className="text-xs font-black text-slate-400 uppercase mb-1">Housing Cost Ratio</p>
                  <div className="flex items-baseline gap-2 mb-2">
                    <span className="text-4xl font-black">{results.housingCostRatio.toFixed(1)}</span><span className="text-lg text-slate-500">%</span>
                  </div>
                  <div className="h-1.5 w-full bg-white/10 rounded-full overflow-hidden">
                    <div className={`h-full ${results.housingCostRatio > 35 ? 'bg-rose-500' : 'bg-emerald-500'}`} style={{width: `${Math.min(100, results.housingCostRatio)}%`}} />
