import React, { useState, useEffect } from 'react';
import { SimulationInputs, SimulationResults, BuildingType } from './types';
import { INITIAL_VALUES } from './constants';
import { calculateSimulation, formatCurrency } from './utils/calculations';
import { getAIAnalysis, extractPropertyFromUrl, getHazardAnalysis, getExitStrategyData } from './services/geminiService';
import { 
  TrendingUp, 
  Wallet, 
  RefreshCcw, 
  BrainCircuit,
  Calculator,
  Zap,
  Loader2,
  BadgeDollarSign,
  CheckCircle2,
  XCircle,
  Scale,
  ReceiptJapaneseYen,
  BarChart3,
  Waves,
  History,
  PiggyBank,
  PlusCircle,
  MinusCircle,
  Info,
  Building2,
