  const bucket2_gains = 
    results.sellingPrice + 
    results.totalMortgageTaxCredit;

  // 純利益
  const netInvestmentResult = bucket2_gains - bucket1_costs;
  const realMonthlyCost = netInvestmentResult >= 0 ? 0 : Math.abs(netInvestmentResult / (inputs.yearsHeld * 12));

  // 賃貸コスト
  const rentalBase = results.estimatedMonthlyRent;
  const rentalManagement = rentalBase * 0.05;
  const rentalRenewalMonthly = (rentalBase / 24);
  const totalMonthlyRental = rentalBase + rentalManagement + rentalRenewalMonthly;

