                            {formatCurrency(save.results.netProfit)}
                          </p>
                        </div>
                        <div className="bg-slate-50 rounded-xl p-3">
                          <p className="text-[8px] font-black text-slate-400 uppercase mb-1">月間住居費</p>
                          <p className="text-sm font-black text-slate-800">
                            {formatCurrency(save.results.monthlyHousingCost)}
                          </p>
                        </div>
                        <div className="bg-slate-50 rounded-xl p-3">
                          <p className="text-[8px] font-black text-slate-400 uppercase mb-1">坪単価</p>
                          <p className="text-sm font-black text-blue-600">
                            {formatCurrency(save.results.purchasePricePerSqM * 3.305785)}
                          </p>
                        </div>
                        <div className="bg-slate-50 rounded-xl p-3 text-center">
                          <p className="text-[8px] font-black text-slate-400 uppercase mb-1 text-left">賃料㎡単価</p>
                          <p className="text-sm font-black text-indigo-600">
                            {formatCurrency(save.results.rentPerSqM)}
                          </p>
                        </div>
                      </div>

                      <button 
                        onClick={() => handleLoadSimulation(save)}
                        className="mt-auto w-full py-3 bg-slate-900 text-white rounded-xl text-xs font-black flex items-center justify-center gap-2 group-hover:bg-blue-600 transition-all"
                      >
                        <Copy size={14} /> この条件を読み込む
                      </button>
                    </div>
                  ))}
                </div>
              </section>
            )}
          </div>
        </div>
      </main>
    </div>
  );
};

export default App;

