                    </a>
                    <a 
                      href={suumoSearchUrl || '#'} target="_blank" rel="noopener noreferrer"
                      className={`py-2 px-3 rounded-xl font-bold text-[10px] flex items-center justify-center gap-1 transition-all ${
                        suumoSearchUrl ? 'bg-[#b3d300] text-[#000] hover:opacity-90' : 'bg-slate-100 text-slate-400 cursor-not-allowed'
