/**
 * テキストからJSONを抽出する堅牢な関数
 */
const parseJsonFromText = (text: string) => {
  if (!text) return null;
  try {
    // 1. そのままパース
    return JSON.parse(text);
  } catch {
    try {
      // 2. コードブロックを探す
      const jsonMatch = text.match(/```json\n?([\s\S]*?)\n?```/) || text.match(/```\n?([\s\S]*?)\n?```/);
      if (jsonMatch && jsonMatch[1]) {
        return JSON.parse(jsonMatch[1].trim());
      }
      // 3. 最初の { と 最後の } を探す
      const firstBrace = text.indexOf('{');
      const lastBrace = text.lastIndexOf('}');
      if (firstBrace !== -1 && lastBrace !== -1) {
        return JSON.parse(text.substring(firstBrace, lastBrace + 1));
      }
    } catch (e) {
      console.error("JSON parsing failed:", e);
    }
  }
  return null;
};

export const getAIAnalysis = async (inputs: SimulationInputs, results: SimulationResults) => {
  const prompt = `
    不動産専門家としてアドバイスしてください。
    【物件名】${inputs.propertyName || '未設定'}
    【条件】購入:${inputs.purchasePrice}円, ローン金利:${inputs.interestRate}%, 保有:${inputs.yearsHeld}年
    【結果】売却予想:${results.sellingPrice}円, 純損益:${results.netProfit}円, 家計負担率:${results.housingCostRatio.toFixed(1)}%

    1. 投資としての妥当性 2. リスク（金利や価格下落） 3. 対策 を日本語で簡潔に回答してください。
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
    });
    return { text: response.text };
  } catch (error) {
    return { text: "AI解析中にエラーが発生しました。" };
  }
};

export const extractPropertyFromUrl = async (url: string) => {
  const prompt = `
    Google検索ツールを使用して、指定されたURL（不動産サイト）から以下の物件情報を抽出してください。
    URL: ${url}

    【抽出する項目】
    1. 物件名 (propertyName): マンション名（例：パークタワー勝どきサウス）
    2. 販売価格 (purchasePrice): 円単位の数値（例：5980万円なら59800000）
    3. 専有面積 (areaSize): ㎡単位の数値（例：70.15㎡なら70.15）
    4. 管理費 (maintenanceFee): 月額の数値
    5. 修繕積立金 (repairFund): 月額の数値
    6. 所在地 (propertyAddress): 住所文字列
    7. 物件種別 (buildingType): 全て 'existing' としてください。

    【注意】
    - ページ内の「物件概要」セクションを重点的に探してください。
    - 数字以外の文字（円、万、㎡、ヶ月など）は含めず、純粋な数値に変換してください。
    - 必ず以下のJSON形式1つだけを出力してください：
    {
      "propertyName": "string",
      "purchasePrice": number,
      "areaSize": number,
      "maintenanceFee": number,
      "repairFund": number,
      "propertyAddress": "string",
      "buildingType": "existing",
      "landRatio": 20
    }
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview", // 複雑な抽出のためProモデルを使用
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
      }
    });

    const data = parseJsonFromText(response.text);
    if (!data || (!data.purchasePrice && !data.propertyName)) {
      console.error("Extraction failed. Raw text:", response.text);
      throw new Error("物件情報の読み取りに失敗しました。URLが正しいか確認してください。");
    }

    return { data };
  } catch (error: any) {
    console.error("Extraction Error:", error);
    throw new Error(error.message || "解析エラーが発生しました。");
  }
};

