  Search,
  Settings2,
  Minus,
  Plus,
  HelpCircle,
  MessageSquareText,
  LineChart,
  Map
} from 'lucide-react';

interface SavedSimulation {
  id: string;
  name: string;
  timestamp: number;
  inputs: SimulationInputs;
  results: SimulationResults;
}

const App: React.FC = () => {
  const [inputs, setInputs] = useState<SimulationInputs>(INITIAL_VALUES);
  const [results, setResults] = useState<SimulationResults>(calculateSimulation(inputs));
  const [aiAdvice, setAiAdvice] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);

  const [hazardInfo, setHazardInfo] = useState<{ text: string, sources: {title: string, uri: string}[] } | null>(null);
  const [loadingHazard, setLoadingHazard] = useState(false);
  const [exitStrategy, setExitStrategy] = useState<{ text: string, sources: {title: string, uri: string}[] } | null>(null);
  const [loadingExit, setLoadingExit] = useState(false);

  const [propertyUrl, setPropertyUrl] = useState('');
  const [isExtracting, setIsExtracting] = useState(false);

  // 履歴の状態管理
  const [savedSimulations, setSavedSimulations] = useState<SavedSimulation[]>([]);
  const [saveName, setSaveName] = useState('');

  // 比較リスト内の平均値を算出
  const avgTsuboPrice = savedSimulations.length > 0
    ? savedSimulations.reduce((acc, curr) => acc + (curr.results.purchasePricePerSqM * 3.305785), 0) / savedSimulations.length
    : 0;

  const currentTsuboPrice = results.purchasePricePerSqM * 3.305785;
  const priceDiffPercentage = avgTsuboPrice > 0 
    ? ((currentTsuboPrice - avgTsuboPrice) / avgTsuboPrice) * 100 
    : 0;

  // 賃貸利回りから家賃を計算するガイド機能
  const applyYieldToRent = useCallback(() => {
    const calculatedRent = Math.round((inputs.purchasePrice * (inputs.rentalYield / 100)) / 12 / 1000) * 1000;
    setInputs(prev => ({ ...prev, estimatedMonthlyRent: calculatedRent }));
  }, [inputs.purchasePrice, inputs.rentalYield]);

  // 初回読み込み時にlocalStorageから履歴を取得
  useEffect(() => {
    const stored = localStorage.getItem('condo_sim_history');
    if (stored) {
      try {
        setSavedSimulations(JSON.parse(stored));
      } catch (e) {
        console.error("Failed to load history", e);
      }
    }
  }, []);

  // 履歴が更新されたらlocalStorageに保存
  useEffect(() => {
    localStorage.setItem('condo_sim_history', JSON.stringify(savedSimulations));
  }, [savedSimulations]);

  useEffect(() => {
    setResults(calculateSimulation(inputs));
  }, [inputs]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target;
    const checked = (e.target as HTMLInputElement).checked;
    setInputs(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : 
              (name === 'buildingType' ? value : 
               (name === 'propertyAddress' || name === 'targetStation' || name === 'propertyName' ? value : parseFloat(value) || 0))
    }));
  };

  const handleUrlExtract = async () => {
    if (!propertyUrl) return;
    setIsExtracting(true);
    try {
      const { data } = await extractPropertyFromUrl(propertyUrl);
      setInputs(prev => ({
        ...prev,
        propertyName: data.propertyName || prev.propertyName,
        purchasePrice: data.purchasePrice || prev.purchasePrice,
        areaSize: data.areaSize || prev.areaSize,
        maintenanceFee: data.maintenanceFee || prev.maintenanceFee,
        repairFund: data.repairFund || prev.repairFund,
        propertyAddress: data.propertyAddress || prev.propertyAddress,
        buildingType: (data.buildingType as BuildingType) || prev.buildingType,
      }));
      if (data.propertyAddress) {
        fetchLocationAnalysis(data.propertyAddress);
      }
    } catch (error: any) {
      alert(error.message);
    } finally {
      setIsExtracting(false);
    }
  };

  const fetchLocationAnalysis = async (address: string) => {
    setLoadingHazard(true);
    setLoadingExit(true);
    const [hazard, exit] = await Promise.all([
      getHazardAnalysis(address),
      getExitStrategyData(address, inputs.yearsHeld)
    ]);
    setHazardInfo(hazard);
    setExitStrategy(exit);
    setLoadingHazard(false);
    setLoadingExit(false);
  };

  const runAiAnalysis = async () => {
    setLoadingAi(true);
    const advice = await getAIAnalysis(inputs, results);
    setAiAdvice(advice.text);
    setLoadingAi(false);
  };

  const handleSaveSimulation = () => {
    const newSave: SavedSimulation = {
      id: crypto.randomUUID(),
      name: saveName || inputs.propertyName || inputs.propertyAddress || `物件案 ${savedSimulations.length + 1}`,
      timestamp: Date.now(),
      inputs: { ...inputs },
      results: { ...results }
    };
    setSavedSimulations([newSave, ...savedSimulations]);
    setSaveName('');
  };

  const handleDeleteSimulation = (id: string) => {
    setSavedSimulations(savedSimulations.filter(s => s.id !== id));
  };

  const handleLoadSimulation = (save: SavedSimulation) => {
    setInputs(save.inputs);
    setAiAdvice(null);
    setHazardInfo(null);
    setExitStrategy(null);
    // 再読み込み時にハザードと出口戦略を再解析
    if (save.inputs.propertyAddress) {
      fetchLocationAnalysis(save.inputs.propertyAddress);
    }
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  // 0.1%刻みでの騰落率調整
  const adjustAppreciation = (delta: number) => {
    setInputs(prev => ({
      ...prev,
      appreciationRate: Math.round((prev.appreciationRate + delta) * 10) / 10
    }));
  };

  // CSV出力機能
  const handleExportCSV = () => {
    const rows = [
      ['項目', '値'],
      ['物件名', inputs.propertyName],
      ['物件価格', inputs.purchasePrice],
      ['専有面積', inputs.areaSize + '㎡'],
      ['頭金', inputs.downPayment],
      ['ローン金利', inputs.interestRate + '%'],
      ['ローン期間', inputs.mortgageTerm + '年'],
      ['保有期間', inputs.yearsHeld + '年'],
      ['予想価格変化率', inputs.appreciationRate + '%/年'],
      [],
      ['単価データ', ''],
      ['購入㎡単価', Math.round(results.purchasePricePerSqM)],
      ['賃料㎡単価', Math.round(results.rentPerSqM)],
      [],
      ['シミュレーション結果', ''],
      ['想定売却価格', results.sellingPrice],
      ['最終純利益', results.netProfit],
      ['実質住居コスト/月', results.monthlyHousingCost],
      ['比較対象賃料/月', results.estimatedMonthlyRent],
      [],
      ['年次推移データ', ''],
      ['経過年数', '資産価値', 'ローン残債', '累計支出', '含み益(純資産)', '賃貸累計コスト']
    ];

    results.yearlyData.forEach(data => {
      rows.push([
        data.year + '年',
        Math.round(data.propertyValue),
        Math.round(data.mortgageBalance),
        Math.round(data.cumulativeCost),
        Math.round(data.equity),
        Math.round(data.cumulativeRentalCost)
      ]);
    });

    const csvContent = "\uFEFF" + rows.map(e => e.join(",")).join("\n");
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `condo_simulation_${new Date().toISOString().slice(0,10)}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handlePrint = () => {
    window.print();
  };

  // ①コスト（支出合計）
  const bucket1_costs = 
    inputs.downPayment + 
    results.initialBrokerageFee + 
    results.initialOtherCosts + 
    results.totalMortgagePayments +   
    results.totalMaintenanceCosts +   
    results.totalTaxPaid +            
    results.remainingMortgageBalance + 
    results.sellingCosts + 
    results.taxAmount;

  // ②利益（収入合計）
  const bucket2_gains = 
    results.sellingPrice + 
    results.totalMortgageTaxCredit;

  // 純利益
  const netInvestmentResult = bucket2_gains - bucket1_costs;
  const realMonthlyCost = netInvestmentResult >= 0 ? 0 : Math.abs(netInvestmentResult / (inputs.yearsHeld * 12));

  // 賃貸コスト
  const totalMonthlyRental = inputs.estimatedMonthlyRent + (inputs.estimatedMonthlyRent * 0.05) + (inputs.estimatedMonthlyRent / 24);

  // Google Maps 連携 URL
  const googleMapsUrl = inputs.propertyAddress 
    ? `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(inputs.propertyAddress)}`
    : null;

  const googleRouteUrl = (inputs.propertyAddress && inputs.targetStation)
    ? `https://www.google.com/maps/dir/?api=1&origin=${encodeURIComponent(inputs.propertyAddress)}&destination=${encodeURIComponent(inputs.targetStation)}&travelmode=transit`
    : null;

  // 賃貸相場検索URL
  const homesSearchUrl = inputs.propertyAddress 
    ? `https://www.homes.co.jp/chintai/search/?query=${encodeURIComponent(inputs.propertyAddress)}` 
    : null;
  const suumoSearchUrl = inputs.propertyAddress 
    ? `https://www.suumo.jp/jj/chintai/ichiran/FR301FC001/?ar=030&bs=040&fw=${encodeURIComponent(inputs.propertyAddress)}` 
    : null;

  // 口コミ・査定サイトURL
  const mansionCommunityUrl = inputs.propertyName 
    ? `https://www.google.com/search?q=site:e-mansion.co.jp+${encodeURIComponent(inputs.propertyName)}` 
    : null;
  const ieshilUrl = inputs.propertyName 
    ? `https://www.ieshil.com/search/?q=${encodeURIComponent(inputs.propertyName)}` 
    : null;

  // 売却価格計算ロジック（年次複利）
  const totalAppreciationMultiplier = Math.pow(1 + inputs.appreciationRate / 100, inputs.yearsHeld);
  const appreciationLogicText = `計算式: 購入価格 ${formatCurrency(inputs.purchasePrice)} × (1 + 年騰落率 ${inputs.appreciationRate}% ) ^ ${inputs.yearsHeld}年`;

  return (
    <div className="min-h-screen bg-slate-50 pb-20 font-['Inter','Noto_Sans_JP']">
      <style>{`
        @media print {
          .no-print { display: none !important; }
          body { background: white !important; padding: 0 !important; }
          main { margin-top: 0 !important; padding: 0 !important; }
          .max-w-7xl { max-width: 100% !important; width: 100% !important; margin: 0 !important; }
          .shadow-sm, .shadow-lg, .shadow-2xl { box-shadow: none !important; border: 1px solid #e2e8f0 !important; }
          header { position: static !important; border-bottom: 2px solid #e2e8f0 !important; }
          aside { border: none !important; }
          * { -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important; }
        }
      `}</style>

      <header className="bg-white border-b border-slate-200 sticky top-0 z-50 shadow-sm">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="bg-slate-900 p-1.5 rounded-lg">
              <TrendingUp className="text-white w-6 h-6" />
            </div>
            <h1 className="text-xl font-bold text-slate-800 tracking-tight">Condo Wealth <span className="text-blue-600">Pro</span></h1>
          </div>
          <div className="flex items-center gap-3">
            <button 
              type="button"
              onClick={handleExportCSV}
              className="no-print text-sm bg-emerald-600 text-white px-4 py-2 rounded-xl font-bold flex items-center gap-2 hover:bg-emerald-700 active:scale-95 transition-all shadow-md shadow-emerald-500/20 cursor-pointer"
            >
              <FileSpreadsheet className="w-4 h-4" /> CSV出力
            </button>
            <button 
              type="button"
              onClick={handlePrint}
              className="no-print text-sm bg-blue-600 text-white px-4 py-2 rounded-xl font-bold flex items-center gap-2 hover:bg-blue-700 active:scale-95 transition-all shadow-md shadow-blue-500/20 cursor-pointer"
            >
              <Printer className="w-4 h-4" /> PDF出力
            </button>
            <button 
              type="button"
              onClick={() => {setInputs(INITIAL_VALUES); setHazardInfo(null); setExitStrategy(null);}} 
              className="no-print text-sm text-slate-400 hover:text-rose-600 flex items-center gap-1 active:scale-95 transition-all"
            >
              <RefreshCcw className="w-4 h-4" />
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 mt-8">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
          {/* 設定エリア（サイドバー） */}
          <aside className="lg:col-span-4 space-y-6">

            {/* AI解析 & 外部連携セクション */}
            <section className="no-print bg-slate-900 rounded-2xl shadow-lg p-6 text-white border border-slate-800">
              <div className="flex items-center gap-2 mb-4">
                <BrainCircuit className="w-5 h-5 text-blue-400" />
                <h2 className="text-lg font-bold">AI物件データ解析</h2>
              </div>
              <div className="space-y-4">
                <div className="relative group">
                  <input 
                    type="text" 
                    placeholder="物件URL（SUUMO等）を貼り付け" 
                    value={propertyUrl} 
                    onChange={(e) => setPropertyUrl(e.target.value)}
                    className="w-full pl-4 pr-10 py-3 bg-white/10 border border-white/20 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
                  />
                  {propertyUrl && (
                    <button 
                      type="button"
                      onClick={() => setPropertyUrl('')}
                      className="absolute right-3 top-1/2 -translate-y-1/2 text-white/40 hover:text-white transition-colors"
                      title="URLを消去"
                    >
                      <XCircle size={18} />
                    </button>
                  )}
                </div>
                <button onClick={handleUrlExtract} disabled={isExtracting || !propertyUrl} className="w-full bg-blue-600 hover:bg-blue-500 disabled:bg-slate-700 text-white py-3 rounded-xl font-bold text-sm transition-all flex items-center justify-center gap-2">
                  {isExtracting ? <Loader2 className="w-4 h-4 animate-spin" /> : <Zap className="w-4 h-4 fill-current" />} 解析・反映
                </button>

                {/* 解析済みデータと口コミリンク */}
                { (inputs.propertyName || isExtracting) && (
                  <div className="pt-4 border-t border-white/10 space-y-3">
                    <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest">対象物件</label>
                    <input 
                      type="text"
                      name="propertyName"
                      value={inputs.propertyName}
                      onChange={handleInputChange}
                      className="w-full px-4 py-2 bg-white/5 border border-white/10 rounded-lg text-sm text-blue-300 font-bold focus:outline-none"
                      placeholder="マンション名"
                    />
                    <div className="grid grid-cols-2 gap-2">
                      <a 
                        href={mansionCommunityUrl || '#'} target="_blank" rel="noopener noreferrer"
                        className={`flex items-center justify-center gap-1 py-2 rounded-lg text-[10px] font-bold transition-all ${
                          mansionCommunityUrl ? 'bg-amber-600 text-white hover:bg-amber-500' : 'bg-white/5 text-white/20'
                        }`}
                      >
                        <MessageSquareText size={12} /> マンコミュ
                      </a>
                      <a 
                        href={ieshilUrl || '#'} target="_blank" rel="noopener noreferrer"
                        className={`flex items-center justify-center gap-1 py-2 rounded-lg text-[10px] font-bold transition-all ${
                          ieshilUrl ? 'bg-rose-600 text-white hover:bg-rose-500' : 'bg-white/5 text-white/20'
                        }`}
                      >
                        <LineChart size={12} /> イエシル査定
                      </a>
                    </div>
                  </div>
                )}
              </div>
            </section>

            {/* 基本条件入力セクション */}
            <section className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6">
              <div className="flex items-center gap-2 mb-6">
                <Calculator className="w-5 h-5 text-blue-600" /><h2 className="text-lg font-bold">購入・ローン詳細条件</h2>
              </div>
              <div className="space-y-4 text-sm">
                {/* 所在地 & 地図確認 */}
                <div className="print:border-b print:pb-2">
                  <label className="block text-xs font-black text-slate-400 uppercase mb-1 flex items-center gap-1">
                    <MapPin size={12} /> 所在地（住所）
                  </label>
                  <div className="flex flex-col gap-2">
                    <input 
                      type="text" 
                      name="propertyAddress" 
                      value={inputs.propertyAddress} 
                      onChange={handleInputChange} 
                      className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-xs print:bg-transparent print:border-none print:px-0" 
                      placeholder="例: 東京都港区..." 
                    />
                    {googleMapsUrl && (
                      <a 
                        href={googleMapsUrl} 
                        target="_blank" 
                        rel="noopener noreferrer" 
                        className="no-print w-full py-2 bg-slate-100 text-slate-700 rounded-lg border border-slate-200 hover:bg-blue-600 hover:text-white hover:border-blue-700 flex items-center justify-center gap-2 font-black text-[10px] transition-all"
                      >
                        <Map size={14} /> Googleマップで場所を確認
                      </a>
                    )}
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div className="col-span-2 print:border-b print:pb-2">
                    <label className="block text-xs font-black text-slate-400 uppercase mb-1">購入価格 (円)</label>
                    <input type="number" name="purchasePrice" value={inputs.purchasePrice} onChange={handleInputChange} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg font-black text-lg text-blue-600 print:bg-transparent print:border-none print:px-0" />
                  </div>
                  <div className="print:border-b print:pb-2">
                    <label className="block text-xs font-black text-slate-400 uppercase mb-1 flex items-center gap-1"><Maximize2 size={12} /> 専有面積 (㎡)</label>
                    <input type="number" name="areaSize" value={inputs.areaSize} onChange={handleInputChange} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg font-bold print:bg-transparent print:border-none print:px-0" />
                  </div>
                  <div className="print:border-b print:pb-2">
                    <label className="block text-xs font-black text-slate-400 uppercase mb-1">手取り月収 (円)</label>
                    <input type="number" name="monthlyTakeHomeIncome" value={inputs.monthlyTakeHomeIncome} onChange={handleInputChange} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg font-bold print:bg-transparent print:border-none print:px-0" />
                  </div>
                  <div className="print:border-b print:pb-2"><label className="block text-xs font-black text-slate-400 uppercase mb-1">頭金 (円)</label><input type="number" name="downPayment" value={inputs.downPayment} onChange={handleInputChange} className="w-full px-4 py-2 bg-emerald-50 border border-emerald-200 rounded-lg font-bold text-emerald-700 print:bg-transparent print:border-none print:px-0" /></div>
                  <div className="print:border-b print:pb-2"><label className="block text-xs font-black text-slate-400 uppercase mb-1 flex items-center gap-1"><Clock size={12} /> 期間(年)</label><input type="number" name="mortgageTerm" value={inputs.mortgageTerm} onChange={handleInputChange} className="w-full px-4 py-2 bg-blue-50 border border-blue-200 rounded-lg font-black text-blue-700 print:bg-transparent print:border-none print:px-0" /></div>
                  <div className="print:border-b print:pb-2"><label className="block text-xs font-black text-slate-400 uppercase mb-1">金利 (%)</label><input type="number" step="0.01" name="interestRate" value={inputs.interestRate} onChange={handleInputChange} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg font-bold print:bg-transparent print:border-none print:px-0" /></div>
                  <div className="print:border-b print:pb-2"><label className="block text-xs font-black text-slate-400 uppercase mb-1">保有(年)</label><input type="number" name="yearsHeld" value={inputs.yearsHeld} onChange={handleInputChange} className="w-full px-4 py-2 bg-amber-50 border border-amber-200 rounded-lg font-black text-amber-700 print:bg-transparent print:border-none print:px-0" /></div>
                </div>
              </div>
            </section>

            {/* 通勤・目的地へのアクセスセクション */}
            <section className="no-print bg-white rounded-2xl shadow-sm border border-slate-200 p-6">
              <div className="flex items-center gap-2 mb-4">
                <Navigation className="w-5 h-5 text-blue-600" />
                <h2 className="text-lg font-bold">任意の目的地へのルート</h2>
              </div>
              <div className="space-y-3">
                <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase mb-1">目的地（職場・任意の建物名など）</label>
                  <input 
                    type="text" 
                    name="targetStation" 
                    value={inputs.targetStation} 
                    onChange={handleInputChange} 
                    className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm font-bold focus:ring-2 focus:ring-blue-500 outline-none" 
                    placeholder="例: 大手町駅, 東京スカイツリー"
                  />
                </div>
                <a 
                  href={googleRouteUrl || '#'} 
                  target={googleRouteUrl ? "_blank" : "_self"}
                  rel="noopener noreferrer"
                  className={`w-full py-3 rounded-xl font-bold text-sm flex items-center justify-center gap-2 transition-all ${
                    googleRouteUrl 
                    ? 'bg-blue-600 text-white hover:bg-blue-700 shadow-md shadow-blue-500/20 active:scale-95' 
                    : 'bg-slate-100 text-slate-400 cursor-not-allowed'
                  }`}
                >
                  <Train className="w-4 h-4" /> Googleルートを検索
                </a>
                <p className="text-[9px] text-slate-400 italic">※所在地から目的地までの交通ルートを別タブで開きます。</p>
              </div>
            </section>

            {/* 賃貸相場・比較設定セクション */}
            <section className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6 space-y-4">
              <div className="flex items-center gap-2 mb-2">
                <Settings2 className="w-5 h-5 text-indigo-600" />
                <h2 className="text-lg font-bold">賃貸相場・比較設定</h2>
              </div>

              <div className="space-y-4">
                <div className="p-4 bg-slate-50 rounded-xl border border-slate-100">
                  <label className="block text-xs font-black text-slate-400 uppercase mb-1 flex items-center gap-1">
                    想定利回りからの家賃算出 (%)
                  </label>
                  <div className="flex items-center gap-3">
                    <input 
                      type="number" step="0.1" name="rentalYield" 
                      value={inputs.rentalYield} onChange={handleInputChange}
                      className="w-20 px-3 py-1.5 bg-white border border-slate-200 rounded-lg font-bold text-sm"
                    />
                    <button 
                      onClick={applyYieldToRent}
                      className="flex-1 bg-indigo-50 text-indigo-600 py-1.5 rounded-lg text-xs font-black border border-indigo-100 hover:bg-indigo-600 hover:text-white transition-all"
                    >
                      計算値を適用
                    </button>
                  </div>
